(window.GIM_TS=window.GIM_TS||{})["Sukkah.4"]={"from":96,"a":[["\u0003ואי מייתי\u0004 \u0005[ואם מביא]\u0006 את המים בחבית \u0003מקודשת, איפסילו להו\u0004 \u0005[נפסלו להם]\u0006 המים \u0003בלינה\u0004 במשך הלילה כשאר דברים הקדושים בקדושת הגוף שנפסלים בלינה ושוב לא יהיו ראויים לניסוך. \u0003חזקיה אמר: כלי שרת אין מקדשין אלא מדעת\u0004 שצריך לכוון שיתקדש מה שבכלי, ובעצם היה אפשר להכניס גם בחבית מקודשת, אלא \u0003גזירה\u0004 היא שגזרו שלא ימלאו את המים אלא בחבית שאינה מקודשת \u0003שמא יאמרו\u0004 האנשים לאחר שיראו שמנסכים את המים הללו למחרת בבוקר ויחשבו ש\u0003לדעת נתקדשו\u0004 בתוכה, שאין לינה פוסלת את הנסכים. \u0003אמר ר' ינאי אמר ר' זירא: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי \u0003יש שיעור למים\u0004 וכן תאמר \u0003שכלי שרת אין מקדשין אלא מדעת, גזירה\u0004 אחרת יש כאן: \u0003שמא יאמרו\u0004 כי \u0003ל\u0004צורך \u0003קידוש ידים ורגלים מלאן\u0004 ואין להם שיעור, ולכשיראו שמנסכים אותם יאמרו שאין הנסכים נפסלים בלינה.","","שנינו במשנה שאם \u0003נשפכה או נתגלתה\u0004 החבית — מימיה פסולים. ושואלים: ו\u0003אמאי\u0004 \u0005[ומדוע]\u0006 יפסלו המים? \u0003ליעביד\u0004 \u0005[\u0006ו\u0005שיעשה\u0006 את המים\u0005]\u0006 \u0003במסננת\u0004 ועל ידי כך יתגלה הרעל. \u0003לימא מתניתין\u0004 \u0005[האם נאמר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' נחמיה? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 דבר המכוסה \u0003במסננת — יש בו משום גילוי. אמר ר' נחמיה: אימתי\u0004 הדין כן — \u0003בזמן שהתחתונה\u0004 (הכלי התחתון) \u0003מגולה, אבל בזמן שהתחתונה מכוסה, אף על פי ש\u0004המסננת \u0003העליונה מגולה — אין בה משום גילוי. מפני שארס נחש דומה לספוג\u0004 וספוג \u0003צף ועומד במקומו.\u0004","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' נחמיה, אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' נחמיה,\u0004 להתיר מים מגולים על ידי סינון, זהו דווקא \u0003להדיוט, אבל לגבוה מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 שאף שאפשר להכשיר מים אלה לשתיה ודאי אין אלה מן המובחר. ושואלים: \u0003ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו]\u0006 \u0003לר' נחמיה\u0004 מה שנאמר: \u0003\"הקריבהו נא לפחתך הירצך או הישא פניך אמר ה' צבאות\"\u0004 (מלאכי א, ח)? ומכאן למדנו שדבר שאין אדם נותנו כמתנת כבוד למכובדים בין בני אדם, ודאי שאין ראוי לתתו על גבי המזבח.","","\u0003החליל,\u0004 מנגנים היו בו בחג הסוכות \u0003חמשה\u0004 או \u0003ששה\u0004 ימים. \u0003זהו החליל\u0004 שהיו מנגנים בו בשמחת \u0003בית השואבה, שאינו דוחה לא את השבת ולא את יום טוב.\u0004 ולכן אם חל יום ראשון בשבת, עשוי החליל שינגנו בו או ששה ימים של ימי חול המועד בלבד, או חמישה ימים אם חלה שבת באחד מימי חול המועד."],["\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בשאלה זו \u0003רב יהודה ורב עינא, חד תני\u0004 \u0005[אחד\u0006 מהם \u0005היה שונה]:\u0006 שמחת בית ה\u0003שואבה, וחד תני\u0004 \u0005[ואחד\u0006 מהם \u0005היה שונה]:\u0006 שמחת בית \u0003חשובה. אמר מר זוטרא: מאן דתני\u0004 \u0005[מי ששונה]\u0006 \u0003\"שואבה\" לא משתבש\u0004 \u0005[טועה]\u0006 \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"חשובה\" לא משתבש\u0004 \u0005[טועה].\u0006 והוא מפרט: \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 \u0003\"שואבה\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ושאבתם מים בששון\"\u0004 (ישעיה יב, ג) ועל שם ניסוך המים נקראת השמחה. \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"חשובה\" לא משתבש\u0004 \u0005[טועה],\u0006 שכן \u0003אמר רב נחמן: מצוה חשובה היא ובאה מששת ימי בראשית.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003החליל דוחה את השבת,\u0004 אלו \u0003דברי ר' יוסי בר יהודה. וחכמים אומרים: אף יום טוב אינו דוחה. אמר רב יוסף: מחלוקת\u0004 זו היא לגבי \u0003שיר של קרבן\u0004 שהיו מלוים את הקרבת קרבנות התמיד בשירה. ש\u0003ר' יוסי\u0004 בר יהודה \u0003סבר: עיקר שירה בכלי\u0004 ושירה זו \u0003עבודה היא\u0004 ולכן היא \u0003דוחה את השבת. ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003עיקר שירה\u0004 היא דווקא זו ששרים \u0003בפה,\u0004 ומה שמנגנים בכלי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003עבודה היא\u0004 אלא ליווי ורקע שמוסיפים לעתים לשירה ולכן \u0003אינה דוחה את השבת. אבל שיר של שואבה — דברי הכל שמחה היא\u0004 ואינה חלק מעבודת הקודש, ולכן ודאי \u0003שאינה דוחה את השבת.\u0004","\u0003אמר רב יוסף: מנא אמינא דבהא פליגי\u0004 \u0005[מניין אומר אני שבזה הם חלוקים]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כלי שרת שעשאן של עץ, רבי פוסל ור' יוסי בר יהודה מכשיר. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא\u0006 בדבר \u0005זה נחלקו]:\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003מכשיר סבר\u0004 כי \u0003עיקר שירה בכלי\u0004 הוא ואף כלי הנגינה שבמקדש כלי שרת הם, ודבר זה שניתן לעשות כלי שרת מעץ \u0003ילפינן מאבובא\u0004 \u0005[למדים אנו מן האבוב]\u0006 שהיה מימי \u0003משה\u0004 שהיה עשוי עץ ולשיטה זו כלי שרת היה. \u0003ומאן דפסיל\u0004 \u0005[ומי שפוסל]\u0006 \u0003סבר\u0004 כי \u0003עיקר שירה בפה\u0004 היא, ולכן \u0003לא ילפינן מאבובא\u0004 \u0005[אין אנו למדים מאבוב]\u0006 של \u0003משה,\u0004 שלשיטה זו אינו כלי שרת.","ודוחים: \u0003לא,\u0004 אין להוכיח מכאן, כי אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003עיקר שירה בכלי\u0004 היא, אלא \u0003הכא\u0004 \u0005[כאן]\u0006 בשאלה אם \u0003דנין\u0004 דבר ש\u0003אפשר\u0004 לעשותו \u0003מ\u0004דבר \u0003שאי אפשר קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 כלומר: האם אפשר ליצור הכללה ממקרה פרטי, שיש בו צד מיוחד. \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003מכשיר\u0004 בכל כלי שרת של עץ \u0003סבר\u0004 כי \u0003דנין אפשר משאי אפשר,\u0004 שאף שאכן רוב כלי השרת היו עשויים מתכת ולכאורה מהם היה צריך ללמוד, מכל מקום כיון שמצינו את האבוב שאינו עשוי אלא עץ, יש ללמוד ממנו אף על הכלל ולהכשיר כל כלי שרת העשויים עץ \u0003ומאן דפסיל\u0004 \u0005[ומי שפוסל]\u0006 \u0003סבר: לא דנין\u0004 דבר ש\u0003אפשר\u0004 לעשותו \u0003מ\u0004דבר \u0003שאי אפשר,\u0004 שכיון שאבוב של משה הוא יוצא מן הכלל, אין ללמוד ממנו הלכה כללית.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאפשר לדחות את הוכחת רב יוסף באופן אחר ולהסביר כך: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 יש לומר כי \u0003עיקר שירה בפה\u0004 ואין ללמוד איפוא מאבוב, ואפילו אם תאמר כי עיקר שירה בכלי היא עדיין אי אפשר ללמוד מאבוב, כי לדעת הכל \u0003אין דנין אפשר משאי אפשר, והכא במילף\u0004 \u0005[וכאן\u0006 השאלה היא כיצד \u0005ללמוד]\u0006 דין ה\u0003מנורה,\u0004 האם בדרך לימוד \u0003בכללי ובפרטי\u0004 \u0005[בכללים ופרטים]\u0006 או בדרך לימוד \u0003ברבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים]\u0006 \u0003קא מיפלגי\u0004 \u0005[הוא שנחלקו].\u0006 \u0003רבי דריש\u0004 \u0005[\u0006היה \u0005דורש]\u0006 \u0003כללי ופרטי\u0004 \u0005[כללים ופרטים],\u0006 ואילו \u0003ר' יוסי בר יהודה דריש\u0004 \u0005[\u0006היה \u0005דורש]\u0006 בדרך \u0003ריבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים].\u0006","ואלה פרטי המחלוקת: \u0003רבי\u0004 הפוסל כלי שרת העשויים עץ, \u0003דריש\u0004 \u0005[\u0006היה \u0005דורש]\u0006 \u0003כללי ופרטי\u0004 \u0005[כללים ופרטים],\u0006 וכך למד מן הפסוק \"ועשית מנורת זהב טהור מקשה תיעשה המנורה\" (שמות כה, לא): \u0003\"ועשית מנורת\"\u0004 — הרי זה \u0003כלל,\u0004 שהרי מכאן אפשר ללמוד מנורה של כל דבר, \u0003\"זהב טהור\" — פרט,\u0004 לומר שאין בכלל האמור אלא מה שיש בפרט זה, וללמד שאין לעשותה אלא זהב טהור, \u0003\"מקשה תיעשה המנורה\"\u0004 בלי פירוט החומר — הרי זה \u0003חזר וכלל.\u0004 והרי לנו כאן איפוא \u0003כלל ופרט וכלל,\u0004 ולפי כללי מדרש ההלכה הרי בכגון זה \u0003אי אתה דן אלא כעין הפרט\u0004 שמרחיבים את הכלל לכל דבר שהוא כעין דוגמת הפרט; \u0003מה הפרט מפורש של מתכת, אף כל\u0004 חומר שאפשר לעשות ממנו את המנורה הרי זה \u0003של מתכת\u0004 בלבד.","ואילו \u0003ר' יוסי בר יהודה\u0004 המכשיר כלי שרת העשויים עץ, \u0003דריש\u0004 \u0005[\u0006היה \u0005דורש]\u0006 בדרך \u0003ריבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים],\u0006 וכך למד: \u0003\"ועשית מנורת\"\u0004 הרי זה \u0003ריבה, \"זהב טהור\" — מיעט\u0004 (צמצם), \u0003\"מקשה תיעשה המנורה\" — חזר וריבה,\u0004 הרי \u0003ריבה ומיעט וריבה\u0004 ולפי כללי מידה זו בהלכה — \u0003ריבה הכל.\u0004 וכך לומדים: \u0003מאי רבי\u0004 \u0005[מה ריבה] —\u0006 \u0003רבי כל מילי\u0004 \u0005[ריבה כל דבר]\u0006 כל חומר ואפילו עץ, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מיעט\u0004 על ידי כך — \u0003מיעט\u0004 מנורה \u0003של חרס,\u0004 שאת הדבר הרחוק ביותר מן הכללים ממעטים על ידי הפרט.","\u0003אמר רב פפא:\u0004 גופם של דברי רב יוסף שהמחלוקת בין ר' יוסי בר יהודה וחכמים האם החליל דוחה יום טוב ושבת, היא בדבר מהותה של השירה בעת הקרבת קרבנות התמיד,"],["\u0003כתנאי\u0004 \u0005[כתנאים],\u0006 שכבר נחלקו בענין זה \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת ערכין: המנגנים בכלי הנגינה שבמקדש \u0003עבדי כהנים היו,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: משפחת בית הפגרים ומשפחת בית צפריא,\u0004 ומהעיר \u0003אמאום היו, שהיו\u0004 ישראלים מיוחסים עד שהיו \u0003משיאין\u0004 את בנותיהם \u0003לכהונה,\u0004 ולא היו עבדים.","\u0003ר' חנינא בן אנטיגנוס אומר: לוים היו. מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא\u0006 בנושא \u0005זה נחלקו]\u0006 \u0003דמאן\u0004 \u0005[שמי]\u0006 ש\u0003אמר\u0004 כי \u0003עבדים היו\u0004 המנגנים, \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003עיקר שירה בפה\u0004 והנגינה אינה אלא ליווי שאינו עיקרי ולכן יכלו להיות המנגנים אף עבדים. \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 ש\u0003לויים היו\u0004 המנגנים, \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003עיקר שירה בכלי,\u0004 ולכן היו המנגנים צריכים להיות לויים, שהרי עושים הם את עבודת הלויים בשירה, אבל ישראלים פסולים לכך.","ומקשים: \u0003ותסברא\u0004 \u0005[וסבור אתה]\u0006 שאפשר לפרש כן?! שהרי לפי הסברך זה, \u0003ר' יוסי מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 כי \u0003עיקר שירה בפה\u0004 היא — אם כן \u0003אפילו עבדים נמי\u0004 \u0005[גם כן]\u0006 יכולים לנגן, ומדוע אם כן היה צריך לכך משפחות מיוחסות מישראל, ו\u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 ש\u0003עיקר שירה בכלי —\u0004 אם כן \u0003לוים אין\u0004 \u0005[כן]\u0006 \u0003ישראלים לא!\u0004","\u0003אלא\u0004 אין ממש בפירוש זה, ויש לומר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003עיקר שירה בפה\u0004 והנגינה בכלי אינה עיקר. אלא \u0003בהא קא מיפלגי\u0004 \u0005[בזו נחלקו]:\u0006 \u0003דמר\u0004 \u0005[שחכם זה]\u0006 \u0003סבר: הכי הוה\u0004 \u0005[כך היה]\u0006 ה\u0003מעשה,\u0004 שעשו זאת עבדים, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר: הכי הוה\u0004 \u0005[כך היה]\u0006 ה\u0003מעשה,\u0004 שעשו זאת ישראלים מיוחסים.","ושואלים: אם כן \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם כך או כך היה המעשה? ומשיבים: יש מכאן מסקנה לענין אם \u0003מעלין מדוכן ליוחסין ולמעשר קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 האם העובדה שאדם אחד או אבותיו היו מן המנגנים על הדוכן במקדש משמשת הוכחה לגבי כשרות ייחוסו או לגבי זכותו במעשרות.","\u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ש\u0003עבדים היו\u0004 המנגנים, \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003אין מעלין מדוכן\u0004 לא לענין \u0003יוחסין\u0004 (כשרות יחוסו) \u0003ולא למעשר. ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 ש\u0003ישראל היו\u0004 המנגנים \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 כי \u0003מעלין\u0004 היו \u0003מדוכן\u0004 לענין \u0003יוחסין,\u0004 לומר שכל המנגנים ישראלים כשרים היו, \u0003אבל לא למעשר. ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 כי \u0003לוים היו קסבר\u0004 \u0005[סבור]:\u0006 \u0003מעלין מדוכן בין ליוחסין בין למעשר.\u0004","עד כאן דנו על פי שיטת רב יוסף, \u0003ואילו ר' ירמיה בר אבא אמר: מחלוקת\u0004 ר' יוסי בר' יהודה וחכמים היא דווקא \u0003בשיר של שואבה,\u0004 ש\u0003ר' יוסי בר יהודה סבר: שמחה יתירה נמי\u0004 \u0005[גם כן]\u0006 \u0003דוחה את השבת, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003שמחה יתירה אינה דוחה את השבת. אבל בשיר של קרבן — לדברי הכל\u0004 אף הנגינה \u0003עבודה היא, ודוחה את השבת.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעת רב יוסף שנחלקו בשיר שעל הקרבנות, ממה ששנינו: \u0003שיר של שואבה דוחה את השבת,\u0004 אלו \u0003דברי ר' יוסי בר יהודה, וחכמים אומרים: אף יום טוב אינו דוחה.\u0004 הרי מפורש שנחלקו בענין שיר של שואבה, ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דעת \u0003רב יוסף!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ונדחו דבריו.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 מכאן ולהסיק מברייתא זו כי \u0003בשיר של שואבה\u0004 דווקא \u0003הוא דפליגי\u0004 \u0005[שנחלקו],\u0006 \u0003אבל בשיר של קרבן — דברי הכל דוחה את השבת,\u0004 ואם כן \u0003לימא תיהוי תיובתא\u0004 \u0005[האם לומר שתהא זו קושיא חמורה]\u0006 על דעת \u0003רב יוסף בתרתי\u0004 \u0005[בשתים],\u0006 בשני נושאים!","\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב יוסף: פליגי\u0004 \u0005[חלוקים הם]\u0006 \u0003בשיר של שואבה, והוא הדין\u0004 שחלוקים הם אף בשיר של \u0003קרבן. והאי דקמיפלגי\u0004 \u0005[וזה שנחלקו]\u0006 \u0003בשיר של שואבה\u0004 דווקא — \u0003להודיעך כחו\u0004 של \u0003ר' יוסי בר יהודה\u0004 כמה הפליג בשיטתו ש\u0003אפילו\u0004 נגינה של \u0003שואבה נמי דחי\u0004 \u0005[גם כך דוחה]\u0006 את השבת.","ומקשים: \u0003והא קתני\u0004 \u0005[והרי שונה]\u0006 התנא במשנתנו: \u0003זהו חליל של בית השואבה שאינו דוחה לא את השבת ולא את יום טוב,\u0004 ונדייק: \u0003זהו,\u0004 החליל של בית השואבה הוא ש\u0003אינו דוחה, אבל\u0004 של \u0003קרבן — דוחה,\u0004 ואם כן \u0003מני\u0004 \u0005[כ\u0006דעת \u0005מי היא]\u0006 משנתנו? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 כדעת \u0003ר' יוסי בר יהודה — האמר\u0004 \u0005[הרי אמר]\u0006 \u0003שיר של שואבה נמי\u0004 \u0005[גם כן]\u0006 \u0003דוחה\u0004 את השבת! \u0003אלא לאו רבנן\u0004 \u0005[האם לא\u0006 כשיטת \u0005חכמים]\u0006 היא משנתנו \u0003ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 היא על דעת \u0003רב יוסף בתרתי\u0004 \u0005[בשני\u0006 דברים\u0005]!\u0006 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא.","ושואלים: לגופו של דבר, \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 ש\u0003עיקר שירה בכלי?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר חזקיהו להעלות העולה להמזבח ובעת החל העולה החל שיר ה' והחצצרות ועל ידי כלי דויד מלך ישראל\"\u0004 (דברי הימים ב' כט, כז), משמע ש\"שיר ה'\" על הקרבן הוא זה המתנגן בחצוצרות ושאר כלי נגינה.","ומוסיפים לשאול: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה טעמו של מי שאומר]\u0006 כי \u0003עיקר שירה בפה?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי כאחד למחצרים ולמשררים להשמיע קול אחד\"\u0004 (דברים הימים ב' ה, יג) וכיון שפרט לחצוצרות לא הוזכרו כלי הנגינה אחרים יחד עם המשוררים, משמע שעיקר השיר הוא על ידי המשוררים בפה. שכן החצוצרות אינן עשויות לנגינה ואינן נחשבות ככלי שיר, אלא היו עשויות לתקיעות התמידים והמוספים.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר\u0006 הסובר כי עיקר השיר הוא בפה \u0005גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ויאמר חזקיה\u0004 וגו' \u0003\"\u0004. ומכאן שעיקר שירה בכלי! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך,\u0006 לדעתו \u0005אמר]:\u0006 \u0003\"החל שיר ה'\"\u0004 משמע — \u0003בפה\u0004 שהוא עיקר השיר, \u0003\"על ידי כלי דויד מלך ישראל\" — לבסומי קלא\u0004 \u0005[להמתיק את הקול]\u0006 שאין כלי הנגינה אלא כליווי לשירה.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר\u0006 הסובר כי עיקר השיר בכלי, \u0005גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ויהי כאחד למחצרים ולמשררים\",\u0004 ומכאן שעיקר השיר הוא בפה! ומשיבים: לשיטה שעיקר שירה בכלי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003משררים דומיא\u0004 \u0005[בדומה]\u0006 \u0003דמחצצרים, מה מחצצרים\u0004 כוונתו בודאי \u0003בכלי — אף משוררים\u0004 עושים עבודה זו \u0003בכלי.\u0004","\u0003מי שלא ראה שמחת בית השואבה לא ראה שמחה מימיו.\u0004 וכך היה הסדר: \u0003במוצאי יום טוב הראשון של חג ירדו\u0004 הכהנים והלויים מעזרת ישראל \u0003לעזרת נשים\u0004 שלמטה ממנה \u0003ומתקנין שם תיקון גדול\u0004 כאשר יבואר. \u0003מנורות של זהב היו שם\u0004 בעזרה על גבי עמודים \u0003וארבעה ספלים של זהב בראשיהם, וארבעה סולמות לכל אחד ואחד\u0004 מן העמודים הללו, \u0003וארבעה ילדים מפירחי כהונה\u0004 (כהנים צעירים) \u0003ובידיהם\u0004 היו \u0003כדים של מאה ועשרים לוג שהן מטילין\u0004 שמן \u0003לכל ספל וספל. מבלאי\u0004 (מן הבגדים הבלויים) של \u0003מכנסי כהנים ומהמייניהן\u0004 (ומאבנטיהם), \u0003מהן היו מפקיעין\u0004 (מתירים וקורעים) ועושים מהם פתילות למנורות אלה, \u0003ובהן היו מדליקין.\u0004 והאור היה גדול כל כך, עד \u0003שלא היה חצר בירושלים שאינה מאירה מאור בית השואבה.\u0004","\u0003חסידים ואנשי מעשה היו מרקדין בפניהם\u0004 של הבאים להשתתף בשמחה"],["\u0003באבוקות של אור שבידיהן\u0004 שהיו זורקים כלפי מעלה ותופשים, \u0003ואומרים לפניהם דברי שירות ותושבחות\u0004 לה'. \u0003והלוים\u0004 היו מנגנים \u0003בכנורות ובנבלים ובמצלתים ובחצוצרות ובכלי שיר בלא מספר,\u0004 והיו המנגנים עומדים \u0003על חמש עשרה מעלות\u0004 (מדרגות) \u0003היורדות מעזרת ישראל לעזרת נשים,\u0004 שהן \u0003כנגד חמש עשרה\u0004 שיר ה\u0003מעלות שבתהלים, שעליהן לוים עומדין בכלי שיר ואומרים שירה.\u0004","\u0003ו\u0004כך היה סדר ניסוך המים: \u0003עמדו שני כהנים בשער העליון שיורד מעזרת ישראל לעזרת נשים, ושני חצוצרות בידיהן,\u0004 ומש \u0003קרא הגבר\u0004 (התרנגול) בהשכמת הבוקר — \u0003תקעו והריעו ותקעו.\u0004 וכש\u0003הגיעו\u0004 ממלאי המים \u0003למעלה\u0004 (מדרגה) \u0003עשירית\u0004 מאותן מעלות שבין עזרת ישראל לעזרת נשים — \u0003תקעו והריעו ותקעו\u0004 בעלי החצוצרות לסימן שיש ללכת למלאות מים מן השילוח. \u0003הגיעו\u0004 ממלאי המים עם המים בידיהם \u0003לעזרה\u0004 לעזרת נשים — \u0003תקעו והריעו ותקעו.\u0004","\u0003הגיעו לקרקע\u0004 העזרה — \u0003תקעו והריעו ותקעו.\u0004 וכך \u0003היו תוקעין והולכין עד שהיו מגיעין לשער היוצא ממזרח. הגיעו לשער היוצא ממזרח\u0004 — \u0003הפכו פניהן ממזרח למערב\u0004 כלפי קודש הקדשים \u0003ואמרו: אבותינו\u0004 שחיו בזמן בית ראשון ונהגו שלא כראוי, כ\u0003שהיו במקום הזה\u0004 היו \u0003\"אחריהם אל ההיכל\u0004 היכל ה' \u0003ופניהם קדמה, ומשתחוים\u0004 והמה משתחויתם \u0003קדמה לשמש\"\u0004 (יחזקאל ח, טז), \u0003ואנו ליה עינינו. ר' יהודה אומר,\u0004 כך \u0003היו שונין ואומרין: אנו ליה וליה עינינו.\u0004","כהמשך לדברי המשנה, מספרים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מי שלא ראה שמחת בית השואבה לא ראה שמחה מימיו, מי שלא ראה ירושלים בתפארתה לא ראה כרך נחמד מעולם, מי שלא ראה בית המקדש בבנינו לא ראה בנין מפואר מעולם.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 באיזה מבניני בית המקדש מדובר, של שלמה, של נחמיה, או של הורדוס שהרס את בנין נחמיה ובנאו מחדש? \u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב חסדא: זה בנין הורדוס\u0004 שבנה את בית המקדש לאחרונה ושיפצו ופארו מאוד.","ושואלים: \u0003במאי בניה\u0004 \u0005[במה בנאו]?\u0006 \u0003אמר רבא: באבני שישא\u0004 (שיש אפור נוטה לירוק) \u0003ומרמרא\u0004 (שיש לבן). \u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 שבנה אותו \u0003באבני שישא כוחלא\u0004 (שיש כחול) \u0003ומרמרא\u0004 (שיש לבן). והיו האבנים הללו קבועות בו באופן זה: \u0003אפיק שפה ועייל שפה כי היכי דלקבל סידא\u0004 \u0005[הוציא שורה והכניס שורה\u0006 במקצת כדי \u0005שיוכל הבנין לקבל סיד].\u0006 \u0003סבר למשעיין בדהבא\u0004 \u0005[חשב\u0006 אחר כך \u0005לטוח,\u0006 לכסות את האבנים \u0005ב\u0006ציפוי \u0005זהב],\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו החכמים]:\u0006 \u0003שבקיה\u0004 \u0005[הנח אותו\u0006 כך\u0005]\u0006 בלא ציפוי \u0003דהכי שפיר טפי, דמיתחזי כאדותא דימא\u0004 \u0005[שכך יפה יותר, שהוא נראה כגלי הים]\u0006 בצבעים השונים ובאבנים המונחות כגלים עולים ויורדים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005];\u0006 \u0003ר' יהודה אומר: מי שלא ראה דיופלוסטון\u0004 (בית הכנסת הגדול) \u0003של אלכסנדריא של מצרים לא ראה בכבודן של ישראל. אמרו:\u0004 מבנהו \u0003כמין בסילקי\u0004 (ארמון) \u0003גדולה היתה, סטיו\u0004 (שדרת עמודים) \u0003לפנים מסטיו\u0004 היתה, \u0003פעמים שהיו\u0004 נמצאים \u0003בה ששים רבוא על ששים רבוא\u0004 אנשים, \u0003כפלים כיוצאי מצרים. והיו בה שבעים ואחת קתדראות\u0004 (כסאות) \u0003של זהב כנגד שבעים ואחד של סנהדרי גדולה, כל אחת ואחת\u0004 מקתדראות אלה \u0003אינה פחותה מעשרים ואחד רבוא ככרי זהב. ובימה של עץ באמצעיתה, וחזן\u0004 (שמש) \u0003הכנסת עומד עליה והסודרין\u0004 כעין דגלים \u0003בידו. וכיון שהגיע\u0004 שליח הציבור בברכה במקום שצריך \u0003לענות אמן, הלה\u0004 השמש \u0003מניף בסודר וכל העם עונין אמן,\u0004 שמרוב גודלו של המקום לא יכלו לשמוע את הברכות מפי החזן בשעה שנאמרו.","\u0003ולא היו\u0004 בעלי המלאכה למיניהם \u0003יושבין מעורבין, אלא זהבין\u0004 (צורפי זהב) \u0003בפני עצמן וכספין\u0004 (צורפי הכסף) \u0003בפני עצמן ונפחין בפני עצמן וטרסיים\u0004 (חרשי נחושת) \u0003בפני עצמן וגרדיים\u0004 (אורגים) \u0003בפני עצמן. וכשעני\u0004 זר \u0003נכנס לשם היה מכיר בעלי אומנתו ונפנה לשם. ומשם פרנסתו ופרנסת אנשי ביתו\u0004 שבני מקצועו היו דואגים לו שימצא עבודה במקצוע זה.","וכיון שסופר בגדולתם, מספרים, \u0003אמר אביי: וכולהו קטלינהו\u0004 \u0005[ואת כולם,\u0006 כל באי בית הכנסת, \u0005הרג]\u0006 \u0003אלכסנדרוס מוקדן.\u0004 ושואלים: \u0003מאי טעמא איענשו\u0004 \u0005[מה טעם נענשו]\u0006 שנהרגו כולם? \u0003משום דעברי אהאי קרא\u0004 \u0005[שעברו על כתוב זה],\u0006 שנאמר בציווי ליוצאי מצרים: \u0003\"לא תוספון לשוב בדרך הזה עוד\"\u0004 (דברים יז, טז), \u0003ואינהו הדור אתו\u0004 \u0005[והם חזרו ובאו]\u0006 וכיון שקבעו מקום מגוריהם במצרים נענשו על כך.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 המלך \u0003אשכחינהו דהוו קרו בסיפרא\u0004 \u0005[מצא אותם שהיו קוראים\u0006 באותה שעה \u0005בספר התורה]\u0006 את הכתוב: \u0003\"ישא ה' עליך גוי מרחוק\u0004 מקצה הארץ כאשר ידאה הנשר גוי אשר לא תשמע לשונו\u0003\"\u0004 (דברים כח, מט). \u0003אמר: מכדי ההוא גברא בעי למיתי ספינתא\u0004 \u0005[הרי אותו אדם,\u0006 אני, \u0005רצה לבא\u0006 ב\u0005ספינה\u0006 \u0003בעשרה יומי\u0004 \u0005[ימים]\u0006 מרומי לכאן, \u0003דליה זיקא ואתי ספינתא בחמשא יומי\u0004 \u0005[נשאתו הרוח ובאה הספינה בחמישה ימים],\u0006 אם כן עלי נאמר הכתוב \"כאשר ידאה הנשר\" ומן השמים מסייעים בידי — מיד \u0003נפל עלייהו וקטלינהו\u0004 \u0005[עליהם והרגם].\u0006","שנינו במשנה שב \u0003מוצאי יום טוב\u0004 ראשון היו יורדים הכהנים והלויים לעזרת נשים והיו עושים שם תיקון גדול. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 היה \u0003תיקון גדול\u0004 זה? \u0003אמר ר' אלעזר: כאותה ששנינו: חלקה היתה\u0004 עזרת נשים \u0003בראשונה,\u0004 שלא היה דבר בולט מכתליה, ומאוחר יותר קבעו בהם זיזים. ובכל שנה היו באים לפני שמחת בית השואבה \u0003והקיפוה גזוזטראת\u0004 שהיו מניחים לוחות עץ על גבי זיזים אלו של עץ מלמעלה, \u0003והתקינו שיהו נשים יושבות מלמעלה ואנשים מלמטה\u0004 לצניעות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003בראשונה היו\u0004 עושים שתהיינה ה\u0003נשים\u0004 עומדות בעזרת נשים \u0003מבפנים\u0004 סמוך יותר לקודש במערב \u0003ואנשים\u0004 עומדים \u0003מבחוץ,\u0004 ברחבת הר הבית ובחיל, \u0003והיו באים לידי קלות ראש\u0004 בין האנשים והנשים, שהיו האנשים צריכים להיכנס קרוב יותר למזבח בשעת הקרבת הקרבנות ונתערבו בין הנשים, לכך \u0003התקינו שיהו נשים יושבות מבחוץ ואנשים מבפנים, ועדיין היו באין לידי קלות ראש.\u0004 לכן \u0003התקינו שיהו נשים יושבות מלמעלה ואנשים מלמטה,\u0004 שיהיו נפרדים לגמרי.","ושואלים: \u0003היכי עביד הכי\u0004 \u0005[איך עשו כך]\u0006 לעשות שינויים במבנה בית המקדש? \u0003והכתיב\u0004 \u0005[והלא נאמר]\u0006 במקדש: \u0003\"הכל בכתב מיד ה' עלי השכיל\u0004 כל מלאכות התבנית\u0003\"\u0004 (דברי הימים א' כח, יט), לומר שכל תבנית המקדש ברוח הקודש ניתנה,","וכיצד התירו לעשות שינויים בתבנית זו? \u0003אמר רב: קרא אשכחו ודרוש\u0004 \u0005[כתוב מצאו ודרשו\u0006 אותו\u0005]\u0006 ועל פיו עשו."],["\u0003\"וספדה הארץ משפחות משפחות לבד משפחת בית דויד לבד ונשיהם לבד\u0004 משפחת בית נתן לבד ושניהם לבד\u0003\"\u0004 (זכריה יב, יב), שיהיו מפרידים בין הנשים והגברים. \u0003אמרו: והלא דברים קל וחומר: ומה לעתיד לבא\u0004 בזמן שעליו נאמרה נבואה זו, \u0003שעוסקין בהספד, ו\u0004דרך השרויים בצער ש\u0003אין יצר הרע שולט בהם,\u0004 שאינם מקילים ראש \u0003—\u0004 בכל זאת \u0003אמרה תורה\u0004 שיהיו \u0003אנשים לבד ונשים לבד. עכשיו, שעסוקין בשמחה\u0004 של בית השואבה וכדרך השמחים הריהם מקילים ראשם \u0003ויצר הרע שולט בהם\u0004 — \u0003על אחת כמה וכמה\u0004 שראוי שיהיו לחוד.","כיון שהבאנו כתוב זה על ההספד באחרית הימים, שואלים: \u0003הא הספידא מאי עבידתיה\u0004 \u0005[הספד זה מה מעשהו],\u0006 על איזה מאורע נעשה אותו הספד? ומשיבים: \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בשאלה זו \u0003ר' דוסא ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הספד זה הוא \u0003על משיח בן יוסף שנהרג\u0004 במלחמת גוג ומגוג לפני שתבוא הגאולה השלימה על ידי משיח בן דוד, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הספד זה הוא \u0003על יצר הרע שנהרג.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 כי הספד זה הוא \u0003על משיח בן יוסף שנהרג — היינו דכתיב\u0004 \u0005[הוא שנאמר]:\u0006 \u0003\"והביטו אלי את אשר דקרו וספדו עליו כמספד על היחיד\"\u0004 (זכריה יב, י). \u0003אלא ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 כי \u0003על יצר הרע שנהרג\u0004 נערך מספד זה — \u0003האי הספידא בעי למעבד\u0004 \u0005[לזה הספד צריך לעשות]?\u0006 הרי לכך \u0003שמחה בעי למעבד\u0004 \u0005[צריך\u0006 היה \u0005לעשות]!\u0006 ואם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003בכו?\u0004","ומשיבים: \u0003כדדרש\u0004 \u0005[כפי שדרש]\u0006 \u0003ר' יהודה\u0004 בענין זה, ובדרשתו מסביר גם את ההספד. שאמר: \u0003לעתיד לבא מביאו הקדוש ברוך הוא ליצר הרע ושוחטו בפני צדיקים ובפני הרשעים. צדיקים נדמה להם\u0004 יצר הרע \u0003כהר גבוה, ורשעים נדמה להם כחוט השערה\u0004 בלבד. \u0003הללו בוכין והללו בוכין. צדיקים בוכין ואומרים: היאך יכולנו לכבוש הר גבוה כזה! ורשעים בוכין ואומרים: היאך לא יכולנו לכבוש את חוט השערה הזה! ואף הקדוש ברוך הוא תמה עמהם, שנאמר: \"כה אמר ה' צבאות כי יפלא בעיני שארית העם הזה בימים ההם גם בעיני יפלא\"\u0004 (זכריה ח, ו) וזהו המספד הנזכר שם.","וכיון שדיברו ביצר הרע, בציור דמותו ובמלחמה בו, מביאים מה ש\u0003אמר רב אסי: יצר הרע בתחילה\u0004 שמפתה את האדם \u0003דומה לחוט של בוכיא\u0004 \u0005[של עכביש]\u0006 \u0003ולבסוף דומה כעבותות העגלה, שנאמר: \"הוי מושכי העון בחבלי השוא וכעבות העגלה חטאה\"\u0004 (ישעיה ה, יח), שבתחילה הפיתוי הוא כקורים דקים שאינם נראים (\"שוא\") ולבסוף לכשמתפתה האדם, הריהו קושרו אליו בחוזק כעבותות של עגלה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003משיח בן דוד שעתיד להגלו‍ת במהרה בימינו, אומר לו הקדוש ברוך הוא: שאל\u0004 (בקש) \u0003ממני דבר ואתן לך\u0004 מה שאתה מבקש, \u0003שנאמר: \"אספרה אל חק\u0004 ה' אמר אלי בני אתה \u0003אני היום ילדתיך. שאל ממני ואתנה גוים נחלתך\u0004 ואחוזתך אפסי ארץ\" (תהלים ב, ז-ח). \u0003וכיון שראה משיח בן יוסף\u0004 אשר בא לפניו, \u0003ש\u0004הוא \u0003נהרג, אומר לפניו,\u0004 לפני הקדוש ברוך הוא: \u0003רבונו של עולם! איני מבקש ממך אלא חיים\u0004 שלא אהרג כמוהו. \u0003אומר לו\u0004 הקדוש ברוך הוא: \u0003חיים, עד שלא אמרת\u0004 בקשה זו \u0003כבר התנבא עליך דוד אביך\u0004 בדיוק בענין זה, \u0003שנאמר: \"חיים שאל ממך נתתה לו\u0004 אורך ימים עולם ועד\u0003\"\u0004 (תהלים כא, ה).","\u0003דרש ר' עוירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' יהושע בן לוי: שבעה שמות יש לו ליצר הרע: הקדוש ברוך הוא קראו \"רע\", שנאמר: \"כי יצר לב האדם רע מנעריו\"\u0004 (בראשית ח, כא). \u0003משה קראו\u0004 בכינוי \u0003\"ערל\", שנאמר: \"ומלתם את ערלת לבבכם\"\u0004 (דברים י, טז). \u0003דוד קראו \"טמא\", שנאמר: \"לב טהור ברא לי אלהים\"\u0004 (תהלים נא, יב), ומדייקים: \u0003מכלל דאיכא\u0004 \u0005[מכאן שיש]\u0006 לב \u0003טמא\u0004 והוא היצר הרע.","\u0003שלמה קראו \"שונא\", שנאמר: \"אם רעב שנאך האכילהו לחם ואם צמא השקהו מים, כי גחלים אתה חותה על ראשו וה' ישלם לך\"\u0004 (משלי כה, כא-כב). \u0003אל תקרי\u0004 (תקרא) \u0003\"ישלם לך\" אלא \"ישלימנו לך\",\u0004 כלומר: שה' יעשה שיהיה יצר האדם שלם עימו ויאהבנו ולא יסיתנו לחטוא ובדרך זו להביאו לאבדון.","\u0003ישעיה\u0004 הנביא \u0003קראו \"מכשול\", שנאמר: \"סלו סלו פנו דרך הרימו מכשול מדרך עמי\"\u0004 (ישעיה נז, יד). \u0003יחזקאל קראו \"אבן\", שנאמר: \"והסרתי את לב האבן מבשרכם ונתתי לכם לב בשר\"\u0004 (יחזקאל לו, כו). \u0003יואל קראו \"צפוני\", שנאמר: \"ואת הצפוני ארחיק מעליכם\"\u0004 (יואל ב, כ). על כתוב זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בכוונת הכתוב \u0003\"ואת הצפוני ארחיק מעליכם\" — זה יצר הרע,\u0004 ומדוע נקרא \"צפוני\" — \u0003שצפון ועומד בלבו של אדם.\u0004","\u0003\"והדחתיו אל ארץ ציה ושממה\"\u0004 (יואל ב, כ) — \u0003למקום שאין בני אדם מצויין\u0004 שלא יוכל \u0003להתגרות בהן.\u0004 ומה מעשיו ונזקיו של יצר זה? \u0003\"את פניו אל הים הקדמוני\"\u0004 (יואל ב, כ) — \u0003שנתן עיניו במקדש ראשון\u0004 (\"קדמוני\" — מלשון מוקדם) \u0003והחריבו והרג תלמידי חכמים שבו. \"וספו אל הים האחרון\" — שנתן עיניו במקדש שני\u0004 (\"אחרון\") \u0003והחריבו, והרג תלמידי חכמים שבו. \"ועלה באשו ותעל צחנתו\"\u0004 (יואל ב, כ) — מפני \u0003שמניח אומות העולם ומתגרה בשונאיהם של ישראל\u0004 (כלומר, בלשון נקיה — ישראל), שיצר הרע מפתה את ישראל יותר מבני כל אומה אחרת. \u0003\"כי הגדיל לעשות\"\u0004 (יואל ב, כ) — \u0003אמר אביי: ובתלמידי חכמים\u0004 מתגרה \u0003יותר מכולם.\u0004","וכעין ראיה לדבר \u0003כי הא\u0004 \u0005[כפי\u0006 מעשה \u0005זה]\u0006 ש\u0003אביי שמעיה לההוא גברא דקאמר לההיא אתתא\u0004 \u0005[שמע אדם אחד שאמר לאשה אחת]:\u0006 \u0003נקדים וניזיל באורחא\u0004 \u0005[ונלך בדרך].\u0006 כיון ששמע, \u0003אמר\u0004 אביי בלבו: \u0003איזיל אפרשינהו מאיסורא\u0004 \u0005[אלך\u0006 ללוותם ועל ידי כך \u0005אפריש אותם מן האיסור]\u0006 שהם מתכוננים ודאי לעשות יחד. \u0003אזל בתרייהו תלתא פרסי באגמא\u0004 \u0005[הלך אחריהם שלוש פרסאות בתוך האגם]\u0006 במקום הקנים, והם היו מהלכים בדרך ולא עשו כל רע. \u0003כי\u0004 \u0005[כאשר]\u0006 הגיעו לפרשת דרכים אשר ממנה היה יכול כל אחד מהם לפנות למקומו, \u0003הוו פרשי מהדדי\u0004 \u0005[היו נפרדים זה מזו],\u0006 ובתוך כדי כך \u0003שמעינהו דקא אמרי\u0004 \u0005[שמע אותם שהם אומרים]:\u0006 \u0003אורחין רחיקא\u0004 \u0005[דרכנו רחוקה],\u0006 כלומר: רב המרחק בין מקומות מגורינו ושוב איננו יכולים להמשיך ללכת באותה דרך, ואולם אילו היינו יכולים להמשיך ללכת באותה דרך, הרי שהיתה \u0003צוותין בסימא\u0004 \u0005[חברתנו נעימה].\u0006","\u0003אמר אביי: אי מאן דסני לי הוה\u0004 \u0005[אם מי ששונא לי היה זה],\u0006 כלומר: אלו הייתי אני בעצמי במצב זה, \u0003לא הוה מצי לאוקומיה נפשיה\u0004 \u0005[הייתי יכול להעמיד עצמי]\u0006 ולהתאפק מלחטוא. כיון שכך ראה בעצמו חסרון גדול זה \u0003אזל תלא נפשיה בעיבורא דדשא\u0004 \u0005[הלך נשען על בריח הדלת]\u0006 והיה מהרהר \u0003ומצטער. אתא ההוא סבא, תנא ליה\u0004 \u0005[בא זקן אחד, שנה לו]:\u0006 \u0003כל הגדול מחבירו יצרו גדול הימנו.\u0004 ולכן אין על אביי להצטער כל כך, שלפי גדולתו כך גם יצרו גדול.","\u0003אמר ר' יצחק: יצרו של אדם מתגבר עליו בכל יום, שנאמר: \"רק\u0004"],["\u0003רע כל היום\"\u0004 (בראשית ו, ה) שכל היום כולו מחשבתו וחפצו לרע. \u0003אמר ר' שמעון בן לקיש: יצרו של אדם מתגבר עליו בכל יום ומבקש להמיתו, שנאמר: \"צופה רשע לצדיק ומבקש להמיתו\"\u0004 (תהלים לז, לג) ו\"רשע\" זהו הרשע הפנימי שבלב, \u0003ואלמלא הקדוש ברוך\u0004 הוא \u0003שעוזר לו\u0004 לאדם בכך שנתן לו יצר טוב — \u0003אינו יכול לו\u0004 להתגבר, \u0003שנאמר: \"ה' לא יעזבנו בידו ולא ירשיענו בהשפטו\"\u0004 (תהלים לז, לב).","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אם פגע בך מנוול זה\u0004 יצר הרע לפתותך — \u0003משכהו לבית המדרש,\u0004 כלומר, למד תורה. \u0003אם אבן הוא\u0004 יצר הרע — הרי הוא \u0003נימוח\u0004 על ידי התורה, \u0003אם ברזל הוא — מתפוצץ.\u0004 ומפרט: \u0003אם אבן הוא — נימוח, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"הוי כל צמא לכו למים\"\u0004 (ישעיה נה, א) ואין \"מים\" אלא תורה, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"אבנים שחקו מים\"\u0004 (איוב יד, יט), שאפילו אבנים נשחקות על ידי המים. \u0003אם ברזל הוא מתפוצץ, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הלא כה דברי כאש נאם ה' וכפטיש יפצץ סלע\"\u0004 (ירמיה כג, כט), לומר שכשם שהאש ממיסה את הברזל, כך דבריו של הקדוש ברוך הוא שהם תורתו, מבטלים את כוחו של היצר הרע.","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: יצר הרע מסיתו לאדם בעולם הזה\u0004 לחטוא, \u0003ו\u0004הוא עצמו \u0003מעיד עליו\u0004 שחטא \u0003לעולם הבא. שנאמר: \"מפנק מנער עבדו ואחריתו יהיה מנון\"\u0004 (משלי כט, כא), כלומר, מתחילה — מנוער, הרי יצר הרע, שהיה יכול להיות באופן טבעי עבד לאדם, משתלט עליו וגורם לו לעשות רע, ובסוף הימים נעשה מנון, ומה הוא \"מנון\" — עד, \u0003שכן באטב\"ח של ר' חייא\u0004 באל\"ף-בי\"ת סודי שהיה ר' חייא משתמש בו שבו מחליפים האות א' ב-ט' ואת ה-ב' ב-ח' וכן הלאה, \u0003קורין לסהדה\u0004 \u0005[עד]\u0006 \u0003מנון.\u0004","\u0003רב הונא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה בין כתובים\u0005]\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד: \u0003\"כי רוח זנונים התעה\"\u0004 (הושע ד, יב), לומר שרוח זנונים זו שהיתה בהם אינה אלא טעות ואינה כחלק מהם. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"\u0004כי רוח זנונים \u0003בקרבם\"\u0004 (הושע ה, ד), הרי שהיא נחשבת כחלק מהם! ומסבירים: \u0003בתחלה התעם\u0004 מבחוץ להם \u0003ולבסוף\u0004 הוא \u0003בקרבם.\u0004","\u0003אמר רבא: בתחלה קראו\u0004 הכתוב ליצר הרע \u0003\"הלך\"\u0004 שהוא כזר הבא מרחוק, \u0003ולבסוף קראו \"אורח\"\u0004 שאדם מקבלו בתוכו, \u0003ולבסוף קראו \"איש\",\u0004 כלומר: אישיות חשובה, כמו בעל הבית. \u0003שנאמר\u0004 במשל שאמר נתן לדוד: \u0003\"ויבא הלך לאיש העשיר ויחמול לקחת מצאנו ומבקרו לעשות לאורח\"\u0004 (שמואל ב' יב, ד) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 הלאה: \u0003\"ויקח את כבשת האיש הראש ויעשה לאיש הבא אליו\"\u0004 (שמואל ב' יב, ד), הרי שאותו הלך (שהוא משל ליצר) נעשה חשוב מפעם לפעם עד שמגיע לדרגת בעל הבית.","\u0003אמר ר' יוחנן: אבר קטן יש לו לאדם\u0004 המשמשו בתשמיש המיטה, ומטבעו שאם \u0003מרעיבו\u0004 שמשמש מעט — הרי הוא \u0003שבע\u0004 ואינו מתאווה ביותר, אולם אם \u0003משביעו\u0004 כלומר שמשמש הרבה — הרי הוא \u0003רעב\u0004 ותאב ביותר, \u0003שנאמר: \"כמרעיתם וישבעו\u0004 שבעו וירם לבם על כן שכחוני\u0003\"\u0004 (הושע יג, ו).","\u0003אמר רב חנא בר אחא: אמרי בי\u0004 \u0005[אמרו\u0006 החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: ארבעה\u0004 דברים כביכול \u0003מתחרט עליהן הקדוש ברוך הוא שבראם,\u0004 לפי שהם גורמים רע יותר מן התועלת שמביאים, \u0003ואלו הן: גלות, כשדים וישמעאלים ויצר הרע. גלות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועתה מה לי פה נאם ה' כי לקח עמי חנם\"\u0004 (ישעיה נב, ה), שכביכול ה' עצמו שואל: מה לי פה. \u0003כשדים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הן ארץ כשדים זה העם לא היה\"\u0004 (ישעיה כג, יג), כלומר: הלוואי שלא היה.","\u0003ישמעאלים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ישליו אהלים לשדדים ובטחות למרגיזי אל לאשר הביא אלוה בידו\"\u0004 (איוב יב, ו). כלומר: אותם שודדים, שהם הערבים הדרים במדברות בתוך אהלים, הוא עצמו כביכול גרם לעצמו בהרגזתו להביאם לעולם. \u0003יצר הרע\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ביום ההוא נאום ה' אוספה הצולעה והנידחה אקבצה \u0003ואשר הרעתי\"\u0004 (מיכה ד, ו), שכביכול אומר ה' שהרע לעשות בבריאתו.","בדומה לכך \u0003אמר ר' יוחנן: אלמלא שלש מקראות הללו,\u0004 שבכולם נלמד שהקדוש ברוך הוא שולט על לב האדם \u0003נתמוטטו רגליהם של שונאיהן של ישראל\u0004 (של ישראל, בלשון נקיה) שלא היתה להם תקומה מפני חטאיהם. \u0003חד דכתיב\u0004 \u0005[אחד\u0006 מהם, \u0005שנאמר]:\u0006 \u0003\"ואשר הרעתי\",\u0004 משמע שהקדוש ברוך הוא מצטער על הדבר הזה אשר גרם להם. \u0003וחד דכתיב\u0004 \u0005[ואחד שנאמר]:\u0006 \u0003\"הנה כחומר ביד היוצר כן אתם בידי בית ישראל\"\u0004 (ירמיה יח, ו). \u0003ואידך\u0004 \u0005[ו\u0006כתוב \u0005אחר]:\u0006 \u0003\"והסרתי את לב האבן מבשרכם ונתתי לכם לב בשר\"\u0004 (יחזקאל לו, כו), משמע שהדבר הוא בידי הקדוש ברוך הוא ולא רק בידי אדם.","\u0003רב פפא אמר: אף מהאי נמי\u0004 \u0005[מ\u0006כתוב \u0005זה גם כן]:\u0006 \u0003\"ואת רוחי אתן בקרבכם\u0004 ועשיתי את אשר בחוקי תלכו ומשפטי תשמרו ועשיתם\" (יחזקאל לו, כז).","אגב פירושי הכתובים המדברים בדבר קץ הימים מביאים עוד כתוב ומפרשים אותו. נאמר: \u0003\"ויראני ה' ארבעה חרשים\"\u0004 (זכריה ב, ג). ושואלים: \u0003מאן נינהו\u0004 \u0005[מי הם]\u0006 אותם \u0003ארבעה חרשים\u0004 שראה? \u0003אמר רב חנא בר ביזנא אמר ר' שמעון חסידא:\u0004 אלה הם \u0003משיח בן דוד, ומשיח בן יוסף, ואליהו, וכהן צדק,\u0004 הכהן הגדול שיהיה בזמן ביאת המשיח. \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, וכי \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בהמשך הדברים: \u0003\"ויאמר אלי אלה הקרנות אשר זרו את יהודה\"\u0004 (זכריה ב, ב), הרי דבר זה לא יתכן שהרי משמע כי \u0003הני לשובה אתו\u0004 \u0005[אלה לצריה הם באים]\u0006 ואינם גואלים לישראל, כפירושך!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שפיל לסיפיה דקרא\u0004 \u0005[רד\u0006 וקרא \u0005את סופו של הכתוב]:\u0006 \u0003\"ויבאו אלה להחריד אתם לידות את קרנות הגוים הנושאים קרן אל ארץ יהודה לזרותה וגו'\"\u0004 (זכריה ב, ד), משמע ש\"קרנות\" אלה הכוונה לאומות שזרו את ישראל בגולה, וארבעת החרשים האמורים הם המפילים את הקרנות שהן הסמל לאויבים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת; \u0003בהדי\u0004 \u0005[ביחד],\u0006 כלומר: להתווכח עם ר' \u0003חנא באגדתא\u0004 \u0005[באגדה]\u0006 \u0003למה לי,\u0004 הלא בקי הוא ממני בתחום זה, ואיני יכול לו.","ועוד דרשו; נאמר: \u0003\"והיה זה שלום אשור כי יבוא בארצנו וכי ידרך בארמנותינו והקמנו עליו שבעה רעים ושמנה נסיכי אדם\"\u0004 (מיכה ה, ד). ושואלים: \u0003מאן נינהו\u0004 \u0005[מי הם]\u0006 \u0003\"שבעה רועים\"\u0004 אלה? ומסבירים: \u0003דוד באמצע, אדם שת ומתושלח מימינו, אברהם יעקב ומשה משמאלו. ומאן נינהו\u0004 \u0005[ומי הם]\u0006 \u0003\"שמנה נסיכי אדם\" — ישי ושאול, ושמואל, עמוס, וצפניה, צדקיה, ומשיח ואליהו.\u0004","ושוב לפירושה של המשנה; שנינו כי \u0003ארבעה סולמות\u0004 היו בעמודים שהיו הפנסים עליהם במקדש. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003גובהה של מנורה\u0004 כלומר: של העמוד שמניחים עליו את הפנסים \u0003— חמשים אמה.\u0004 שנינו במשנה: \u0003וארבעה ילדים של פרחי כהונה\u0004 (כהנים צעירים) \u0003ובידיהם כדי שמן של מאה ועשרים לוג. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003מאה ועשרים לוג כולהו\u0004 \u0005[כולם\u0006 יחד\u0005]\u0006 היו מביאים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 בפני עצמו מביא כמות זו? ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מברייתא ששנינו: \u0003ובידיהם כדי שמן של שלשים שלשים לוג שהם כולם מאה ועשרים לוג.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003והן\u0004 פרחי כהונה שעשו זאת \u0003משובחין היו\u0004 בכוחם \u0003יותר מבנה של מרתא בת בייתוס\u0004 שהיה כהן ומפורסם היה בגבורתו. \u0003אמרו על בנה של מרתא בת בייתוס שהיה נוטל שתי יריכות של שור הגדול,\u0004 וזה היה גדול כל כך עד \u0003ש\u0004היה \u0003לקוח\u0004 \u0005[נקנה]\u0006 \u0003באלף זוז, ומהלך\u0004 על הכבש \u0003עקב בצד גודל,\u0004 כלומר: בפסיעות קטנות ולא במרוצה שכוחו היה רב כל כך לשאת את כל אלה. \u0003ולא הניחוהו אחיו הכהנים לעשות כן\u0004 שיקח את שתי הירכות, \u0003משום \"ברב עם הדרת מלך\"\u0004 (משלי יד, כח), שיש בעבודת כהנים רבים משום כבוד לה'. ומשום כך צריכים כמה כהנים לשאת את יריכו של השור.","ושואלים: \u0003מאי\u0004 \u0005[במה]\u0006 \u0003משובחים\u0004 הם פרחי כהונה? \u0003אילימא משום יוקרא\u0004 \u0005[אם תאמר משום כובד]\u0006 המשקל, שהיו יכולים לשאת משקל שלושים לוג בבת אחת — \u0003הני יקירי טפי\u0004 \u0005[אותן\u0006 שתי יריכות הרי \u0005כבדות יותר]\u0006 משלושים לוג. \u0003אלא\u0004 יש לומר: \u0003התם\u0004 \u0005[שם]\u0006 במעשה בנה של מרתא היה זה הילוך על \u0003כבש\u0004 והוא רחב \u0003ומרובע ולא זקיף\u0004 \u0005[זקוף]\u0006 אלא יש בו שיפוע קל, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 היו הם צריכים להלך על גבי \u0003סולמות וזקיף טובא\u0004 \u0005[\u0006והיו אלה \u0005זקופים ביותר]\u0006 ובכל זאת היו פרחי כהונה עולים בהם ולא נכשלו.","שנינו במשנה: \u0003ולא היה חצר בירושלים\u0004 שלא האירה מאור מנורות השואבה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006"],["\u0003אשה היתה בוררת חטים לאור של בית השואבה\u0004 שעד כדי כך היה האור מרובה.","שנינו במשנה כי \u0003חסידים ואנשי מעשה\u0004 היו שרים לפניהם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא: \u0003יש מהן\u0004 שהיו \u0003אומרים\u0004 בשירם כשבח לקדוש ברוך הוא: \u0003אשרי ילדותנו\u0004 שלא חטאנו בצעירותינו, \u0003שלא ביישה\u0004 בשל כך \u0003את זקנותנו — אלו חסידים ואנשי מעשה\u0004 שהיו כל ימיהם עוסקים בתורה ומצוות. \u0003ויש מהן אומרים: אשרי זקנותנו שכפרה את ילדותנו\u0004 לאחר שחטאנו בהיותנו צעירים — \u0003אלו בעלי תשובה. אלו ואלו אומרים: אשרי מי שלא חטא, ומי שחטא — ישוב וימחול לו\u0004 ה'.","\u0003תניא\u0004 \u0005[שנויה\u0006 תוספתא\u0005]:\u0006 \u0003אמרו עליו על הלל הזקן, כשהיה שמח בשמחת בית השואבה,\u0004 היה דורש בפני הציבור ומפציר בהם לבל יחטאו, ו\u0003אמר כן,\u0004 דעו כי כך אומר הקדוש ברוך הוא: \u0003אם אני כאן,\u0004 שחפץ אני בבית הזה ומשרה אני בו את שכינתי — \u0003הכל כאן,\u0004 שיהא כבודו קיים ויבואו כולם אליו, \u0003ואם איני כאן,\u0004 שאסלק את שכינתי ממנו אם תחטאו — הרי \u0003מי כאן,\u0004 מי הוא זה שיחפוץ לבוא לכאן. וכן \u0003הוא היה אומר כן: למקום שאני אוהב — שם רגלי מוליכות אותי,\u0004 ולכן אני בא למקדש. ואף הקדוש ברוך הוא אומר: \u0003אם\u0004 אתה \u0003תבא אל ביתי — אני אבא אל ביתך, אם אתה לא תבא אל ביתי — אני לא אבא אל ביתך, שנאמר: \"בכל המקום אשר אזכיר את שמי אבוא אליך וברכתיך\"\u0004 (שמות כ, כא).","כיון שהוזכר הלל הזקן מזכירים אימרה אחרת שלו: \u0003אף הוא ראה גלגולת אחת שצפה על פני המים, אמר לה: על דאטפת אטפוך ומטיפיך יטופון\u0004 \u0005[על שהטבעת —\u0006 \u0005הטביעוך, ומטביעיך\u0006 — \u0005יטובעו],\u0006 שכך הדרך שכל אדם נענש ונגזר עליו מידה כנגד מידה. כהמשך לדברי הלל שרגלי אדם מוליכות אותו למקום האהוב עליו, \u0003אמר ר' יוחנן\u0004 פתגם שונה במקצת: \u0003רגלוהי דבר איניש אינון ערבין ביה\u0004 \u0005[רגליו של אדם הם ערבות בו],\u0006 \u0003לאתר דמיתבעי\u0004 \u0005[למקום שהוא מתבקש\u0006 שם\u0005] —\u0006 \u0003תמן מובילין יתיה\u0004 \u0005[לשם הן מובילות אותו].\u0006","ומספרים: \u0003הנהו תרתי כושאי דהוו קיימי קמי\u0004 \u0005[אותם שני כושיים שהיו עומדים לפני]\u0006 \u0003שלמה; \"אליחרף ואחיה בני שישא\"\u0004 (מלכים א' ד, ג) ו\u0003סופרים\u0004 של \u0003שלמה הוו\u0004 \u0005[היו].\u0006 \u0003יומא חד חזייה\u0004 \u0005[יום אחד ראה]\u0006 שלמה את \u0003מלאך המות דהוה קא עציב\u0004 \u0005[שהוא עצוב],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי עציבת\u0004 \u0005[מדוע אתה עצוב]?\u0006 \u0003אמר ליה: דקא בעו מינאי\u0004 \u0005[שרוצים ממני]\u0006 שאקח את נפשם של \u0003הני תרתי כושאי דיתבי הכא\u0004 \u0005[שני הכושים היושבים כאן].\u0006 \u0003מסרינהו\u0004 \u0005[מסר אותם]\u0006 שלמה \u0003לשעירים,\u0004 השדים שהיו משמשים את שלמה, \u0003שדרינהו למחוזא דלוז\u0004 \u0005[\u0006ו\u0005שלח אותם\u0006 על ידיהם \u0005למחוז לוז]\u0006 ששם אין שליטה למוות. \u0003כי מטו למחוזא דלוז שכיבו\u0004 \u0005[כאשר הגיעו למחוז לוז מתו].\u0006","\u0003למחר חזיא\u0004 \u0005[ראה]\u0006 שלמה את \u0003מלאך המות דהוה קבדח\u0004 \u0005[שהוא שמח]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי בדיחת\u0004 \u0005[מדוע אתה שמח]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המות: \u0003באתר דבעו מינאי, תמן שדרתינהו\u0004 \u0005[במקום שביקשו ממני\u0006 שאקחם משם, לשם \u0005שלחת אותם].\u0006 שכן הורו לו ליטול את נפשם במחוז לוז, ומאחר והיו יושבים בבית שלמה ולא הגיעו מעולם ללוז, לא היתה לו אפשרות לבצע את שהוטל עליו ולכך היה עצב בתחילה. ומאחר שבסופו של דבר הגיעו ללוז בהוראת שלמה, ניתנה לו ההזדמנות לעשות כן ונטל את נפשם ובשל כך היה שמח. ואז \u0003מיד פתח שלמה ואמר: רגלוהי דבר איניש אינון ערבין ביה, לאתר דמיתבעי, תמן מובילין יתיה\u0004 \u0005[רגליו של אדם הן ערבות בו, למקום שהוא מתבקש לשם הן מובילות אותו].\u0006","ועוד בענין שמחת בית שואבה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו עליו על רבן שמעון בן גמליאל כשהיה שמח שמחת בית השואבה היה נוטל שמנה אבוקות של אור\u0004 (אש), \u0003וזורק אחת ונוטל אחת\u0004 והיו כולן באויר \u0003ואין נוגעות זו בזו. וכשהוא משתחוה,\u0004 היה \u0003נועץ שני גודליו בארץ ושוחה\u0004 (מתכופף) \u0003ונושק את הרצפה וזוקף, ואין כל בריה יכולה לעשות כן\u0004 לפי שהוא מעשה קשה ביותר, \u0003וזו היא קידה\u0004 שהיה עושה הכהן הגדול.","ומספרים: החכם \u0003לוי אחוי\u0004 \u0005[הראה]\u0006 כיצד עושים \u0003קידה קמיה\u0004 \u0005[לפני]\u0006 \u0003רבי ואיטלע\u0004 \u0005[ונעשה צולע],\u0006 שנקעה ירכו מחמת המאמץ. ושואלים: \u0003והא גרמא ליה\u0004 \u0005[וכי זה\u0006 שעשה קידה \u0005הוא שגרם לו]\u0006 להיות צולע? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: לעולם לא יטיח\u0004 (יזרוק) \u0003אדם דברים כלפי מעלה\u0004 בתפילתו, שלא יבוא בטענות קשות כלפי הקדוש ברוך הוא, \u0003שהרי אדם גדול הטיח דברים כלפי מעלה,\u0004 ואף שנענה בתפילתו נענש \u0003ואיטלע\u0004 \u0005[ונעשה צולע],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 זה — \u0003לוי.\u0004 הרי שצליעתו נבעה בשל סיבה אחרת! ומשיבים: אין זו סתירה, \u0003הא והא גרמא ליה\u0004 \u0005[זה וזה גרם לו],\u0006 שמפני שהטיח דברים אירע לו שבשעת המאמץ נעשה צולע.","ומספרים: \u0003לוי הוה מטייל קמיה דרבי בתמני סכיני\u0004 \u0005[היה מהלך\u0006 וזורק \u0005לפני רבי שמונה סכינים]\u0006 באויר, ואילו \u0003שמואל\u0004 היה עושה כן \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003בתמניא מזגי חמרא\u0004 \u0005[בשמונה כוסות\u0006 זכוכית המלאים \u0005יין]\u0006 ולא היה היין נשפך, ו\u0003אביי\u0004 היה עושה כן \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבה בתמניא ביעי\u0004 \u0005[בשמונה ביצים],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה עושה כן \u0003בארבעה ביעי\u0004 \u0005[ביצים],\u0006 וכל זה אגב אותו סיפור שסיפרנו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' יהושע בן חנניה,\u0004 שהיה לוי: \u0003כשהיינו שמחים שמחת בית השואבה, לא ראינו שינה בעינינו\u0004 כל אותם הימים. \u0003כיצד\u0004 היה סדר היום? \u0003שעה ראשונה\u0004 של יום היה קרב \u0003תמיד של שחר\u0004 והיו באים לראות בהקרבתו, \u0003משם\u0004 היו הולכים \u0003לתפלה\u0004 לבית הכנסת הסמוך, \u0003משם\u0004 היו הולכים לראות בהקרבת \u0003קרבן מוסף, משם\u0004 הולכים לבית הכנסת ומתפללים \u0003תפלת המוספין, משם\u0004 היו הולכים \u0003לבית המדרש\u0004 ללמוד, \u0003משם\u0004 היו הולכים \u0003לאכילה ושתיה\u0004 בסוכה, \u0003משם\u0004 הולכים \u0003לתפלת המנחה, משם לתמיד של בין הערבים\u0004 בבית המקדש, \u0003מכאן ואילך\u0004 לאחר התמיד, היה \u0003לשמחת בית השואבה.\u0004","ותוהים: \u0003איני\u0004 \u0005[וכן הוא]\u0006 ויכול אדם לעשות כן? \u0003והאמר ר' יוחנן:\u0004 אדם שאמר: \u0003\"שבועה שלא אישן שלשה ימים\" — מלקין אותו\u0004 על שנשבע לשוא \u0003וישן לאלתר\u0004 (מיד), כי אין אדם יכול להישאר ער שלושה ימים רצופים! \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך צריך להבין את דברי ר' יהושע: \u0003לא טעמנו טעם שינה,\u0004 שלא ישנו שינה כתיקונה, אלא \u0003דהוו מנמנמי אכתפא דהדדי\u0004 \u0005[שהיו מנמנמים זה על כתיפו של זה],\u0006 ואכן לא היו ערים לגמרי כל הזמן.","שנינו במשנה ש\u0003חמש עשרה מעלות\u0004 היו מעזרת נשים לעזרת ישראל כנגד חמש עשרה שיר המעלות שבספר תהלים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לההוא מדרבנן דהוי קמסדר אגדתא קמיה\u0004 \u0005[לאחד החכמים שהיה מסדר אגדות לפניו],\u0006 \u0003אמר ליה: שמיע לך\u0004 \u0005[האם שמעת],\u0006 \u0003הני\u0004 \u0005[אותם]\u0006 \u0003חמש עשרה\u0004 שירי ה\u0003מעלות\u0004 הכתובים בספר תהלים, \u0003כנגד מי אמרם דוד? אמר ליה\u0004 \u0005[לו]\u0006 אותו תלמיד חכם: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: בשעה שכרה דוד שיתין\u0004 שהם המערות והנקבים ביסוד המקדש \u0003קפא תהומא ובעי למשטפא עלמא\u0004 \u0005[צף,\u0006 עלה \u0005התהום ורצה לשטוף את העולם],\u0006 מיד \u0003אמר דוד חמש עשרה מעלות והורידן.\u0004 הקשה לו רב חסדא: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 לא \u0003חמש עשרה \"מעלות\"\u0004 היו צריכים להיקרא אלא \u0003\"יורדות\" מיבעי ליה\u0004 \u0005[היה צריך לו]\u0006 שייקראו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003הואיל ואדכרתן מלתא, הכי אתמר\u0004 \u0005[הואיל והזכרתני את הדבר, כך נאמר\u0006 הדבר\u0005]\u0006 במקורו: \u0003בשעה שכרה דוד\u0004 את ה\u0003שיתין קפא תהומא ובעא למשטפא עלמא\u0004 \u0005[צף,\u0006 עלה \u0005התהום ורצה לשטוף את העולם]\u0006 \u0003אמר דוד: מי איכא דידע אי שרי למכתב\u0004 \u0005[האם יש מי שיודע אם מותר לכתוב]\u0006 \u0003שם\u0004 של קודש"],["\u0003אחספא\u0004 \u0005[על חרס]\u0006 ואם אכן יש מי שברור לו הדבר להיתר, \u0003נשדיה בתהומא ומנח\u0004 \u0005[נזרוק אותו לתהום וינוח\u0006 התהום\u0005]!\u0006 \u0003ליכא דקאמר ליה מידי\u0004 \u0005[לא\u0006 היה מי \u0005שיאמר לו דבר].\u0006 \u0003אמר דוד: כל דידע למימר\u0004 \u0005[כל מי שיודע לומר]\u0006 \u0003ואינו אומר\u0004 לי דבר, \u0003יחנק בגרונו.\u0004 ואז \u0003נשא אחיתופל קל וחומר בעצמו\u0004 מדעתו, ואמר: \u0003ומה לעשות שלום בין איש לאשתו\u0004 בדין סוטה, שבעלה חושד בה שנטמאה עם אחר \u0003אמרה תורה: שמי שנכתב בקדושה ימחה על המים,\u0004 שכן בסוטה מוחקים מגילה שכתוב בה שם ה' במים ששותה הסוטה, \u0003לעשות שלום לכל העולם כולו — על אחת כמה וכמה\u0004 שמותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לדוד: \u0003שרי\u0004 \u0005[מותר]\u0006 הדבר.","\u0003כתב שם אחספא ושדי לתהומא, ונחית תהומא שתסר אלפי גרמידי\u0004 \u0005[כתב שם\u0006 קודש \u0005על חרס וזרק אותו לתהום, וירד התהום שש עשרה אלף אמות].\u0006 \u0003כי חזי דנחית טובא\u0004 \u0005[כאשר ראה שירד\u0006 ב\u0005יותר],\u0006 \u0003אמר: כמה דמידלי\u0004 \u0005[שמורם]\u0006 התהום — \u0003טפי מירטב עלמא\u0004 \u0005[יותר רטוב העולם]\u0006 ומועיל לחקלאות, על כן \u0003אמר חמש עשרה\u0004 שירי \u0003מעלות, ואסקיה חמיסר אלפי גרמידי\u0004 \u0005[והעלוהו\u0006 לתהום \u0005חמש עשרה אלף אמות]\u0006 \u0003ואוקמיה באלפי גרמידי\u0004 \u0005[והעמידוהו\u0006 שיהא התהום \u0005באלף אמות].\u0006 \u0003אמר עולא: שמע מינה סומכא דארעא אלפי גרמידי\u0004 \u0005[למד מכאן כי יסודה,\u0006 עובייה \u0005של הארץ\u0006 עד התהום \u0005אלף אמות].\u0006 ושואלים: \u0003והא חזינן דכרינן פורתא ונפקי מיא\u0004 \u0005[והרי אנו רואים שאנו חופרים מעט ויוצאים מים]\u0006 ואין צריך לחפור אלף אמה! \u0003אמר רב משרשיא: ההוא מסולמא דפרת\u0004 \u0005[זה מסולמות הפרת],\u0006 כלומר ממימי הנהר פרת ושאר הנהרות שמוצאם במקום גבוה ועוברים ומחלחלים דרך האדמה, ומהם יוצאים ובוקעים המים, אבל לא ממימי התהום עצמם.","שנינו במשנה: \u0003ועמדו כהנים בשער העליון שיורד\u0004 מעזרת ישראל וכשהגיעו למעלה עשירית תקעו. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 האם \u0003למעלה עשירית\u0004 משמעו \u0003דנחית\u0004 \u0005[שיורד]\u0006 \u0003חמשה\u0004 מדרגות \u0003וקאי\u0004 \u0005[ועומד]\u0006 \u0003אעשרה\u0004 \u0005[על\u0006 מעלה \u0005עשירית]\u0006 מלמטה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 משמעו \u0003דנחית\u0004 \u0005[שיורד]\u0006 \u0003עשרה וקאי אחמשה\u0004 \u0005[על\u0006 מעלה \u0005חמישית]\u0006 מלמטה? לשאלה זו לא נמצאה תשובה והושארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה כי משהגיעו לשער היוצא ממזרח היו הופכים את פניהם ממזרח למערב, והיו אומרים: אבותינו שחיו בזמן בית המקדש הראשון והיו נוהגים שלא כראוי \"אחוריהם אל היכל ה' ופניהם קדמה והמה משתחויתם קדמה לשמש\" (יחזקאל ח, טז), ואילו אנו — ליה עינינו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ממשמע שנאמר: \"ופניהם קדמה\" איני יודע ש\"אחוריהם אל היכל ה'\"?\u0004 שהרי ההיכל לצד מערב הוא!","\u0003אלא מה תלמוד לומר\u0004 בתחילת הפסוק \u0003\"אחריהם אל היכל ה'\"\u0004 (יחזקאל ח, טז) — דבר זה מרמז לנו שהרעו עוד לעשות, \u0003מלמד שהיו פורעין\u0004 (מגלין) \u0003עצמן ומתריזין\u0004 (מטילין רעי) \u0003כלפי מטה\u0004 כלומר, בלשון נקיה, כלפי צד שכינה.","שנינו במשנה כי בזמן הבית השני היו אומרים: \u0003אנו ליה וליה עינינו.\u0004 ושואלים: \u0003איני\u0004 \u0005[כן הוא]?!\u0006 וכי מותר לעשות כן? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זירא: כל האומר \"שמע\" \"שמע\"\u0004 פעמיים \u0003כאילו אמר \"מודים\" \"מודים\"\u0004 והאומר כך משתקים אותו, שנשמע כמאמין בשתי רשויות, וכיצד הזכירו פעמיים את השם! \u0003אלא הכי אמרי\u0004 \u0005[כך היו אומרים]:\u0006 \u0003המה משתחוים קדמה, ואנו ליה אנחנו מודים, ועינינו ליה מיחלות,\u0004 שלא אמרו את שני השמות יחד.","\u0003אין פוחתין\u0004 בכל יום \u0003מעשרים ואחת תקיעות במקדש, ואין מוסיפין\u0004 בשום יום \u0003על ארבעים ושמונה.\u0004 ומפרטים: \u0003בכל יום היו שם עשרים ואחת תקיעות במקדש: שלש\u0004 תקיעות שתקעו \u0003לפתיחת שערים\u0004 בבוקר, \u0003ותשע לתמיד של שחר, ותשע לתמיד של בין הערבים —\u0004 הרי עשרים ואחת. \u0003ובמוספין\u0004 אם היה יום שמקריבים בו קרבן מוסף, כגון ראש חודש — \u0003היו מוסיפין עוד תשע\u0004 תקיעות לכבוד קרבן המוסף.","\u0003ובערב שבת היו מוסיפין שש\u0004 תקיעות סמוך לשבת: \u0003שלש\u0004 מהן כדי \u0003להבטיל את העם ממלאכה\u0004 שידעו שהשבת מתקרבת וראוי להפסיק לעבוד, \u0003ושלש\u0004 מהן \u0003להבדיל בין קדש לחול\u0004 שתקעו ברגע כניסת השבת.","\u0003ערב שבת שבתוך החג\u0004 (הסוכות) \u0003היו שם ארבעים ושמונה\u0004 תקיעות. כיצד? \u0003שלש\u0004 תקיעות בבקר \u0003לפתיחת השערים, שלש לשער העליון ושלש לשער התחתון, ושלש למילוי המים\u0004 כאשר מתואר סדר הבאת המים לניסוך (לעיל סוכה מח, ב), \u0003ושלש\u0004 כשהיו זוקפים את הערבה \u0003על גבי המזבח, תשע\u0004 תקיעות היו \u0003לתמיד של שחר, ותשע לתמיד של בין הערבים, ותשע למוספין,\u0004 ועוד \u0003שלש להבטיל את העם מן המלאכה, ושלש\u0004 נוספות \u0003להבדיל בין קודש לחול —\u0004 הרי בסך הכל ארבעים ושמונה תקיעות.","מעירים: \u0003מתניתין\u0004 \u0005[משנתנו\u0006 זו\u0005]\u0006 ש\u0003לא\u0004 כשיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: הפוחת\u0004 בתקיעות \u0003לא יפחות\u0004 בשום יום \u0003משבע\u0004 תקיעות, \u0003והמוסיף\u0004 ביום שצריך להוסיף \u0003לא יוסיף על שש עשרה.\u0004 ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 ומסבירים, \u0003ר' יהודה סבר: תקיעה תרועה תקיעה אחת היא,\u0004 ששלוש אלה נחשבות כתקיעה משולבת אחת. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003תקיעה לחוד ותרועה לחוד,\u0004 וכל תרועה נחשבת כשלוש תקיעות. ונמצא שלמעשה מתכוונים הם לדבר אחד, ואינם חולקים אלא בדרך המנין.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003ר' יהודה? אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ותקעתם תרועה\"\u0004 (במדבר י, ו) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 עוד: \u0003\"תרועה יתקעו\"\u0004 (במדבר י, ו), \u0003הא כיצד\u0004 יש לבאר את דברי הכתוב המדבר גם על תקיעת תרועה וגם על תרועת תקיעה? אלא משמע ש\u0003תקיעה ותרועה אחת היא. ורבנן\u0004 \u0005[וחכמים]\u0006 — כתובים אלה לדעתם כך משמעם: הפסוק \u0003ההוא לפשוטה לפניה ולאחריה הוא דאתא\u0004 \u0005[שבא],\u0006 ללמד שלפני השמעת התרועה משמיעים קול פשוט לפניו ולאחריו, הוא קול התקיעה. ושואלים: \u0003ור' יהודה,\u0004 שתוקעים אחת פשוטה \u0003לפניה ולאחריה מנליה\u0004 \u0005[מניין לו]?\u0006 ומסבירים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד הדבר\u0005]\u0006 \u0003מ\u0004מה שנאמר \u0003\"\u0004ותקעתם תרועה \u0003שנית\"\u0004 (במדבר י, ו), משמע: תקיעה נוספת.","ושואלים: \u0003ורבנן מאי טעמייהו\u0004 \u0005[וחכמים מה טעמם]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובהקהיל את הקהל תתקעו ולא תריעו\"\u0004 (במדבר י, ז), \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003תקיעה\u0004 ו\u0003תרועה אחת היא,\u0004 אם כן \u0003אמר רחמנא פלגא דמצוה עביד ופלגא לא עביד\u0004 \u0005[אמרה התורה חצי המצוה עשה וחצי לא תעשה]?\u0006 שאם קול תקיעה הוא קול אחד משולב, מדוע עושים רק מחציתו? אלא משמע שכל אחת מצוה לעצמה היא. ושואלים: \u0003ור' יהודה\u0004 מה עונה הוא על כך? ומשיבים: \u0003ההוא\u0004 כלומר: אותה תקיעה האמורה בעת הקהיל את הקהל \u0003לסימנא בעלמא\u0004 \u0005[לסימן בלבד]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 שזו לא היתה תקיעה של מצוה (שלדעתו היא תמיד משולשת), אלא שימשה כסימן בלבד למחנות, ואין למדים ממנה.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אמרו: אכן, \u0003סימנא\u0004 \u0005[סימן]\u0006 \u0003הוא\u0004 לזה, \u0003ורחמנא שויה\u0004 \u0005[והתורה עשתה אותו]\u0006 \u0003מצוה,\u0004 שלא יקהילו את הקהל אלא בסימן זה. וכיון שכך למדים שכל אחת מצוה לעצמה. \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב כהנא: אין בין תקיעה לתרועה ולא כלום\u0004 שמשמיעים אותן ברצף אחד בלי להפסיק בין זו לזו — \u0003כמאן\u0004 \u0005[כמי]? —\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 היא, שהוא סובר כי תקיעה ותרועה אחת היא. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 הרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך צריך לעשות, ואם כן היה עליו לומר כך, שהלכה כר' יהודה!"],["\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שאפשר לפרש את דבריו \u0003אפילו כ\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 ולומר שבא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן,\u0004 ש\u0003אמר: שמע תשע תקיעות בתשע שעות ביום\u0004 בראש השנה אף על פי שלא היו סמוכות זו לזו — \u0003יצא,\u0004 ולכך \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב כהנא שאין הלכה כן ושאין להפסיק ביניהם הפסקה מרובה.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 אולי ש\u0005כך\u0006 הוא \u0005גם כן]\u0006 ואולי זו היתה אכן כוונת רב כהנא, להפקיע מדברי ר' יוחנן כפי שתירצנו, ולא לומר כשיטת ר' יהודה כפי שהובן תחילה! ומשיבים: \u0003אם כן, מאי\u0004 \u0005[מה]\u0006 פירוש ההדגשה שלו \u0003\"ולא כלום\"?\u0004 שהרי היה צריך לומר שאינו מפסיק הרבה, וכיון שאמר \"ולא כלום\" משמע שאינו מפסיק כלל, וזו אינה אלא כשיטת ר' יהודה.","שנינו במשנה בסדר התקיעות, שהיו תוקעים ב\u0003ערב שבת שבתוך החג\u0004 ארבעים ושמונה תקיעות, ומפרטים היכן ומתי היו תוקעים וכמה תקיעות בכל פעם. ומעירים בענין זה, שהיו תוקעים כשהיו מגיעים למזבח \u0003ואילו למעלה עשירית לא קתני\u0004 \u0005[שנה]\u0006 שסבור שלא תקעו שם. \u0003מתניתין מני\u0004 \u0005[משנתנו כ\u0006שיטת \u0005מי היא]? —\u0006 כשיטת \u0003ר' אליעזר בן יעקב היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003שלש\u0004 תקיעות היו תוקעים כשהיו מגיעים \u0003למעלה עשירית, ר' אליעזר בן יעקב אומר: שלש\u0004 תקיעות היו תוקעים כשהיו זוקפים את הערבה \u0003על גבי המזבח.\u0004","ומסבירים: \u0003האומר\u0004 שהיו תוקעים כשהגיעו \u0003למעלה עשירית — אינו אומר\u0004 שתוקעים בשעת זקיפת הערבה \u0003על גבי המזבח, והאומר\u0004 שהיו תוקעים בשעת זקיפת הערבה \u0003על גבי המזבח אינו אומר\u0004 שהיו תוקעים כשהגיעו \u0003למעלה עשירית.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר בן יעקב?\u0004 ומשיבים: \u0003כיון דתקע\u0004 \u0005[ש\u0006הוא \u0005תוקע]\u0006 \u0003ל\u0004כבוד \u0003פתיחת\u0004 ה\u0003שערים,\u0004 אם כן, כשהגיעו \u0003למעלה עשירית למה לי דתקע\u0004 \u0005[שיתקע]?\u0006 \u0003האי\u0004 \u0005[זה]\u0006 הרי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003שער הוא! הלכך,\u0004 תקיעה בשעת זקיפת הערבה \u0003על גבי המזבח עדיף\u0004 על תקיעה במעלה עשירית. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003כיון\u0004 ש\u0003תקע למילוי המים,\u0004 כלומר: במעלה העשירית שהמעבר דרכה נחשבת כחלק מטכס מילוי המים, אם כן, תקיעה נוספת לזקיפת הערבה \u0003על גבי המזבח למה לי? הלכך\u0004 \u0005[על כן],\u0006 \u0003למעלה העשירית עדיף.\u0004","מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' אחא בר חנינא מדרומא\u0004 \u0005[מן הדרום]\u0006 של ארץ ישראל, מארץ יהודה, \u0003אייתי מתניתא בידיה\u0004 \u0005[הביא ברייתא\u0006 זו \u0005בידו],\u0006 שקיבל אותה מחכמי הדרום. נאמר: \u0003\"ובני אהרן הכהנים יתקעו בחצצרות\"\u0004 (במדבר י, ח), ויש להבין \u0003שאין\u0004 לכאורה \u0003תלמוד לומר\u0004 (לימוד וחידוש במה שנאמר) \u0003\"יתקעו\", ש\u0004הרי \u0003כבר נאמר: \"ותקעתם בחצצרת על עלתיכם ועל זבחי שלמיכם\"\u0004 (במדבר י, י) \u0003ומה\u0004 בכל זאת \u0003תלמוד לומר \"יתקעו\"?\u0004 שנראה שמוסיף הלכה חדשה בתקיעות — לומר כי \u0003הכל לפי\u0004 מספר \u0003המוספין תוקעין.\u0004 ומעירים: \u0003הוא\u0004 ר' אחא בר חנינא \u0003תני לה\u0004 \u0005[שנה\u0006 ברייתא \u0005זו]\u0006 \u0003והוא אמר לה\u0004 \u0005[אותה]\u0006 ופירש שבאה \u0003לומר שתוקעין\u0004 תקיעות מיוחדות לפי מספר המוספים, שאם היו כמה מוספים באותו יום, וכגון שהוא שבת ויום טוב, תוקעים תקיעות מיוחדות \u0003על כל מוסף ומוסף\u0004 בפני עצמו.","על כך מקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003ערב שבת שבתוך החג היו שם ארבעים ושמונה\u0004 תקיעות וזה מספר התקיעות הגדול ביותר. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי ר' אחא בר חנינא, אם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003שבת שבתוך החג\u0004 שאז \u0003משכחת לה חמשין וחד\u0004 \u0005[מוצא אתה\u0006 שתוקעים בה \u0005חמישים ואחת]\u0006 תקיעות, שהרי צריכים להוסיף עוד שלוש תקיעות למוספי השבת! \u0003אמר ר' זירא:\u0004 אכן מוסיפים תקיעות מיוחדות למוסף השבת, ובכל זאת עדיין הם ארבעים ושמונה תקיעות בלבד \u0003לפי שאין תוקעין\u0004 את אותם שלוש תקיעות שהיו תוקעים \u0003לפתיחת שערים בשבת,\u0004 שאין תקיעה זו אלא לסימן ולא תקעו בשבת.","\u0003אמר רבא: מאן הא דלא חש לקימחא\u0004 \u0005[מי הוא זה שאינו חושש לקמחו],\u0006 כלומר: לדברים שמוציא מפיו? \u0003חדא\u0004 \u0005[\u0006טענה \u0005אחת]\u0006 כנגד תירוץ זה — שהרי כשמפרטת המשנה את סדר התקיעות ובכללם גם התקיעות לפתיחת השערים, הרי לשון \u0003\"בכל יום\" תנן\u0004 \u0005[שנינו],\u0006 ו\"בכל יום\" משמע גם בשבת. \u0003ועוד, אי נמי כהדדי נינהו\u0004 \u0005[אם גם כן זה כמו הם],\u0006 שאף אם אתה מפחית בשבת שלוש תקיעות של פתיחת שערים, נמצא שאף בשבת יש ארבעים ושמונה, על כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003שבת שבתוך החג היו שם ארבעים ושמונה.\u0004 והיתה תועלת לומר זאת, ולא כאמור במשנה (\"ערב שבת שבתוך החג\"), שהרי על ידי כך \u0003שמעת מינה תרתי\u0004 \u0005[היית שומע,\u0006 לומד \u0005ממנה שני\u0006 דברים\u0005]\u0006 של חידוש: \u0003שמעת מינה\u0004 \u0005[היית שומע ממנה]\u0006 שהמשנה סבורה כשיטת \u0003ר' אליעזר בן יעקב\u0004 שאין תוקעים למעלה העשירית אלא לזקיפת הערבה על גבי המזבח, \u0003ושמעת מינה\u0004 \u0005[\u0006והיית \u0005שומע ממנה]\u0006 את זו שאמר \u0003ר' אחא בר חנינא,\u0004 שתוקעים על כל מוסף ומוסף.","\u0003אלא אמר רבא:\u0004 יש לתרץ באופן אחר, \u0003לפי שאין תוקעין למילוי מים בשבת\u0004 שהרי במשנה שנינו שבשבת לא היו ממלאים מן המים, \u0003דבצרי טובא\u0004 \u0005[שמועטים הרבה יותר],\u0006 שהרי כל אותן התקיעות של מילוי המים בכל המקומות השונים לא היו בשבת. ומקשים עוד: \u0003וליתני נמי\u0004 \u0005[ושישנה גם כן]\u0006 \u0003ראש השנה שחל להיות בשבת, דהא איכא תלתא\u0004 \u0005[שהרי יש\u0006 בו \u0005שלושה]\u0006 \u0003מוספין; מוסף\u0004 של \u0003ראש השנה, מוסף\u0004 של \u0003ראש חודש, ומוסף\u0004 של \u0003שבת,\u0004 ואם כן נמצאו אז גם כן ארבעים ושמונה תקיעות.","ודוחים: יתכן שאכן כך הוא, אלא \u0003ערב שבת שבתוך החג איצטריך ליה\u0004 \u0005[הוצרך לו]\u0006 והעדיף לשנות, כדי \u0003לאשמעינן\u0004 \u0005[להשמיע לנו]\u0006 שהוא פוסק הלכה \u0003כר' אליעזר בן יעקב\u0004 שלא היו תוקעים למעלה העשירית. ומקשים: \u0003אטו מי קאמר ליתני הא ולא ליתני הא\u0004 \u0005[וכי האם אמר שישנה זה ולא ישנה זה]?\u0006 \u0003ליתני הא וליתני הא\u0004 \u0005[שישנה זה וישנה זה],\u0006 שכיון שיש גם בכך חידוש, יביא שני אלה כדוגמאות! ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר,\u0004 שהתנא של משנתנו לא הביא את כל האפשרויות והביא דוגמה אחת מתוך שתים ושייר את השאר. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד, שאתה יכול לטעון שגם \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 של ראש השנה \u0003שייר?\u0004 שכן אין זה מדרכו של התנא לשייר דבר אחד בלבד!","ומשיבים: \u0003שייר\u0004 את מספר התקיעות שתוקעים ב\u0003ערב הפסח,\u0004 שבשעת הקרבת קרבן הפסח היו קוראים את ההלל, ובכל פעם שקראו הלל תקעו בכל פרק של הלל שלוש תקיעות. וכיון שתמיד שחטו את הפסח בשלוש קבוצות, נמצא שהוסיפו אז עשרים ושבע תקיעות לפחות, ואם מצרפים אותן לעשרים ואחת תקיעות שממילא היו תוקעים בכל יום, הרי כבר ארבעים ושמונה תקיעות!"],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003משום ערב הפסח — לאו שיורא הוא\u0004 \u0005[אין זה שיור],\u0006 \u0003דהא מני\u0004 \u0005[ש\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי הוא]\u0006 כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר:\u0004 אף שהיו שלוש כיתות בזו אחר זו עושות את הפסח, מכל מקום \u0003מימיהם של כת שלישית לא הגיעה לומר\u0004 אפילו עד לכתוב \u0003\"אהבתי כי ישמע ה'\"\u0004 (תהלים קטז, א) שהוא פרק שני של ההלל, \u0003מפני שהיו עמה מועטין\u0004 ועד שהגיעו באמירת ההלל לפרק זה, כבר סיימו לשחוט את כל הפסחים, ואם כן לא תקעו עבור כת זו אלא שלוש תקיעות בלבד, ושוב אין לך אלא ארבעים ושתים.","על דחיה זו תוהים: \u0003הא אוקימנא\u0004 \u0005[הרי\u0006 כבר \u0005העמדנו,\u0006 הסברנו\u0005]\u0006 מקודם שמשנתנו ש\u0003לא כ\u0004שיטת \u0003ר' יהודה,\u0004 שהרי לשיטתו תקיעה ותרועה ותקיעה אינם נחשבות אלא לאחת, ואם כן לשיטה זו ודאי שלא מצינו מנין הזהה לאחד מאלה המוזכרים במשנה, וכיצד רוצה אתה שוב לצרף אותה לשיטת ר' יהודה? ומשיבים: \u0003ודלמא האי\u0004 \u0005[ושמא אותו]\u0006 \u0003תנא סבר לה כוותיה בחדא\u0004 \u0005[סבר כמותו ב\u0006דבר \u0005אחד]\u0006 לגבי כת שלישית בערב הפסח, \u0003ופליג עליה בחדא\u0004 \u0005[וחלק עליו ב\u0006דבר \u0005אחד]\u0006 בדרך חישוב מנין התקיעות. ואם כן אין להוכיח מערב הפסח.","\u0003אלא\u0004 אם כן, חוזרת השאלה ששאלנו קודם: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד ש\u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003שייר?\u0004 ומשיבים: \u0003שייר ערב הפסח שחל להיות בערב שבת,\u0004 שאז \u0003אפיק שית\u0004 \u0005[הוצא שש\u0006 תקיעות\u0005]\u0006 מתקיעות הכת השלישית \u0003ועייל שית\u0004 \u0005[והכנס שש\u0006 אחרות\u0005]\u0006 שהיו תוקעים בכל ערב שבת להבטיל את העם ממלאכה ולהכריז על כניסת השבת. ונמצא שיש ארבעים ושמונה תקיעות גם בערב פסח זה.","שנינו במשנה ש\u0003אין מוסיפין על ארבעים ושמונה\u0004 תקיעות. ותוהים: \u0003ולא?\u0004 וכי אין מוסיפים, \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 מקרה כזה כאשר \u0003ערב הפסח שחל להיות בשבת, דאי\u0004 \u0005[שאם]\u0006 לשיטת \u0003ר' יהודה\u0004 לפחות \u0003חמשין וחדא\u0004 \u0005[חמישים ואחת]\u0006 תקיעות הן: עשרים ואחת של כל יום, ותשע יתירות למוסף השבת, ותשעה נוספות להלל הנאמר בשעת הקרבת הפסח של כל אחת משתי הכתות הראשונות ושלוש נוספות לכת השלישית, \u0003אי לרבנן\u0004 \u0005[\u0006ו\u0005אם\u0006 לדעת \u0005חכמים]\u0006 שאף לכת השלישית היו תוקעים תשע תקיעות, אם כן \u0003חמשין\u0004 \u0005[חמישים]\u0006 \u0003ושבע\u0004 תקיעות הן, ואם כן פעמים שיש הרבה יותר מארבעים ושמונה!","ומשיבים: \u0003כי קתני, מידי דאיתיה\u0004 \u0005[כאשר שנה\u0006 החכם, שנה \u0005דבר שישנו]\u0006 \u0003בכל שנה,\u0004 ואילו \u0003ערב הפסח שחל להיות בשבת, דליתיה\u0004 \u0005[שאיננו]\u0006 מצוי \u0003בכל שנה ושנה, לא קתני\u0004 \u0005[שנה].\u0006 ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003ערב שבת שבתוך החג מי איתיה\u0004 \u0005[האם ישנו]\u0006 \u0003בכל שנה?\u0004 הרי \u0003זימנין דלא משכחת ליה\u0004 \u0005[פעמים שאין אתה מוצא אותו].\u0006 \u0003והיכי דמי\u0004 \u0005[וכיצד מזדמן]\u0006 להיות, שלא יהיה ערב שבת בתוך שבוע החג \u0003כגון שחל יום טוב ראשון בערב שבת,\u0004 שאז ערב שבת שלאחריו הוא כבר שמיני עצרת.","ומשיבים: דבר כזה אינו קורה, \u0003כי מקלעינן\u0004 \u0005[כאשר מזדמן לנו]\u0006 \u0003יום טוב ראשון\u0004 של חג \u0003בערב שבת — מדחי דחינן ליה\u0004 \u0005[דוחים אנו אותו],\u0006 שדוחים את ראש השנה ביום אחד (על ידי עיבור חודש אלול). \u0003מאי טעמא\u0004 \u0005[ומה טעם]\u0006 הדבר, \u0003כיון דאיקלע\u0004 \u0005[שהזדמן]\u0006 ש\u0003יום טוב הראשון של חג\u0004 חל \u0003להיות בערב שבת, יום הכפורים אימת הוי\u0004 \u0005[מתי יהיה]\u0006 בשנה כזו — \u0003בחד\u0004 \u0005[באחד]\u0006 \u0003בשבת,\u0004 וכדי שלא יהיו שני ימי שבתון חמורים סמוכים זה לזה, \u0003הלכך דחינן ליה\u0004 \u0005[על כן דוחים אנו אותו]\u0006 את ראש השנה, וממילא אף אין אפשרות שיחול יום טוב הראשון של סוכות בערב שבת.","ושואלים: \u0003ומי דחינן ליה\u0004 \u0005[והאם דוחים אנו אותו],\u0006 באופן שלעולם אין יום הכיפורים חל ביום הראשון בשבוע? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חלבי שבת\u0004 כלומר, חלבי תמיד של בין הערבים שנשחט והוקרב בשבת, ועדיין לא נשרפו על גבי המזבח \u0003קריבין ביום הכיפורים\u0004 שחל להיות אחר השבת,","\u0003ואמר ר' זירא: כי הוינן בי\u0004 \u0005[כאשר הייתי בבית]\u0006 \u0003רב בבבל\u0004 והייתי לומד שם, \u0003הוה אמרי\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003יום הכיפורים שחל להיות בערב שבת — לא היו תוקעין\u0004 להבטיל את העם ממלאכה ולהודיע על כניסת השבת, שהרי בלא כן היו העם בטלים ממלאכה בגלל יום הכיפורים, ואם חל יום הכיפורים \u0003במוצאי שבת — לא היו מבדילין\u0004 אחר השבת, שאין מבדילים אלא בין קודש לחול או בין קדושה חמורה לקדושה הקלה ממנה, ויום הכיפורים קדושתו חמורה מזו של שבת ולכך אין להבדיל ביניהם — לדעתי, ברייתא זו \u0003דברי הכל היא.\u0004 ואולם \u0003כי סליקית להתם\u0004 \u0005[כאשר עליתי לשם,\u0006 לארץ ישראל\u0005]\u0006 \u0003אשכחתיה\u0004 \u0005[מצאתיו]\u0006 את \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי, דיתיב וקאמר\u0004 \u0005[שיושב ואומר]:\u0006 דבר זה שיטת \u0003ר' עקיבא היא,\u0004 לענין קדושת יום הכיפורים, ולא כשיטת חכמים אחרים. ומכל מקום רואים אנו משני מקורות אלה כי יתכן שיום הכיפורים יחול ביום הראשון, ואז חוזרת שאלתנו למקומה, שלא בכל שנה עשוי ערב שבת לחול בתוך ימי החג ומדוע הזכירתו המשנה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 משנתנו ממנה משמע כי ערב שבת חל בתוך ימי החג בכל שנה, כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, הסבורים שדוחים את ראש השנה כדי שלעולם לא יהא יום הכיפורים ביום הראשון וממילא לא יחול יום טוב הראשון בשבת, ואילו \u0003הא\u0004 \u0005[זו]\u0006 המשנה האומרת כי חלבי שבת קרבים ביום הכיפורים שלמחרתו, שממנה משמע כי אין דוחים לעולם, שיטת \u0003אחרים היא,\u0004 הסבורים שיש מנין קבוע לימות השנה ולעולם אין דוחים את ראשי החדשים, ואין משנים לעולם את מספר ימיהם.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אחרים אומרים: אין בין עצרת\u0004 (חג השבועות) \u0003לעצרת\u0004 שבשנה הבאה, \u0003ואין בין ראש השנה לראש השנה\u0004 הבאה \u0003אלא ארבעה ימים בלבד,\u0004 שתמיד יחול אותו חג ארבעה ימים מאוחר יותר בשנה הבאה. שאם בשנה זו הוא חל ביום ראשון בשבוע — הריהו יחול בשנה הבאה ביום חמישי. שמספר ימות השנה הוא לעולם שלוש מאות וחמישים וארבעה יום, שהם חמישים שבועות שלמים ועוד ארבעה ימים. \u0003ואם היתה\u0004 זו \u0003שנה מעוברת\u0004 יש הבדל של \u0003חמשה\u0004 ימים, מפני שמוסיפים עשרים ותשעה יום לאדר שני. וכיון שלשיטתו מספר ימי השנה קבוע נמצא שראש השנה עשוי לחול בכל יום ויום מימות השבוע.","לאחר הדיון בנושאים אחרים, שבים לעסוק בדברי ר' אחא שבימים שיש בהם כמה מוספים, תוקעים תקיעות מיוחדות לכבוד כל מוסף ומוסף. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003ראש חדש שחל להיות בשבת — שיר של ראש חדש דוחה שיר של שבת. ואי איתא\u0004 \u0005[ואם יש]\u0006 מקום לדברי ר' אחא שעבור כל קרבן תוקעים במיוחד, \u0003לימא\u0004 \u0005[שיאמר]\u0006 שיר של \u0003שבת\u0004 לחוד \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 של \u0003ראש חדש\u0004 לחוד, ולכאורה משמע שאין שרים ותוקעים אלא פעם אחת!","\u0003אמר רב ספרא,\u0004 כך יש להבין: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003דוחה —\u0004 כוונתו \u0003דוחה לקדם,\u0004 ששיר של ראש חודש מקדימים לשיר של שבת, ואכן נאמרים השירים של שניהם, ולשיטת ר' אחא אף יתקעו לשניהם בנפרד. ומקשים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יקדים של ראש חודש לשל שבת? והלא כלל בידינו: \u0003תדיר ושאינו תדיר — תדיר קודם,\u0004 שכל מצוה המצויה יותר, מקדימים לעשותה ואחריה עושים את המצוה שהיא פחות מצויה, ומכיון ששבת תדירה מראש חודש צריכה היא לקדום!","\u0003אמר ר' יוחנן:\u0004 מקדימים של ראש חודש שלא לפי הכללים הקבועים, כדי \u0003לידע\u0004 ולהודיע לשומעים \u0003שהוקבע ראש חדש בזמנו\u0004 על ידי בית הדין. ושואלים: \u0003והאי היכירא עבדינן\u0004 \u0005[וכי היכר זה עושים]\u0006 כדי להודיע שהוקבע החודש בזמנו? \u0003הא היכירא אחריתא עבדינן\u0004 \u0005[והרי היכר אחר עושים]\u0006 לצורך זה! \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 כדי למנוע עירבוב חלבי הקרבנות השונים והקטרת דבר הצריך להיקרב מאוחר יותר לפני המוקדם, היו עושים היכר בכך ש\u0003חלבי תמיד של שחר\u0004 היו \u0003ניתנין\u0004 טרם הקרבתם \u0003מחצי כבש ולמטה ב\u0004צד \u0003מזרח\u0004 של הכבש, \u0003ושל מוספין ניתנין מחצי כבש ולמטה במערב, ושל ראש חדש ניתנין תחת כרכוב המזבח ולמטה\u0004 ממנו קצת."],["\u0003ואמר ר' יוחנן:\u0004 מדוע עושים זאת — לסימן \u0003לידע שהוקבע ראש חדש בזמנו\u0004 לאחר עשרים ותשעה ימי חודש הקודם. הרי מצינו שעשו לכך היכר אחר. ומשיבים: זו אינה קושיה, כי \u0003תרי היכירא עבדינן\u0004 \u0005[שני\u0006 מיני \u0005היכרים עושים אנו]\u0006 \u0003דחזי האי\u0004 \u0005[הרואה\u0006 את \u0005זה]\u0006 את זמן השיר — \u0003חזי\u0004 \u0005[רואה],\u0006 \u0003וחזי בהאי\u0004 \u0005[והרואה את זה]\u0006 את המקום בו הניחו את החלבים — \u0003חזי\u0004 \u0005[רואה],\u0006 ואין כאן סתירה.","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' אחא \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רבא בר שמואל\u0004 ברייתא זו: \u0003יכול כשם שתוקעין על\u0004 קרבן \u0003שבת בפני עצמו, ועל ראש חדש בפני עצמו כך יהיו תוקעין על כל מוסף ומוסף\u0004 אם חלו שניהם באותו יום — \u0003תלמוד לומר:\u0004 \"וביום שמחתכם ובמועדיכם \u0003ובראשי חדשיכם\u0004 ותקעתם בחצוצרות על עולותיכם ועל זבחי שלמיכם והיו לכם לזכרון לפני אלהיכם אני ה' אלהיכם\" (במדבר י, י), לומר שאין תוקעים אלא אחת, ומכאן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 \u0003לר' אחא!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","כיון שהבאנו ברייתא זו, שואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד\u0006 שבה\u0005]?\u0006 כלומר: כיצד מוכיחים מן האמור \"ובראשי חדשיכם\" שתוקעים למוסף אחד בלבד? \u0003אמר אביי: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ובראשי חדשיכם\",\u0004 לומר: \u0003הוקשו\u0004 (הושוו) \u0003כל\u0004 ה\u0003חדשים כולם זה לזה,\u0004 וכשם שבשאר ראשי חדשים תוקעים רק למוסף אחד, אף בכגון זה אין תוקעים אלא תקיעה אחת ולא יותר. \u0003רב אשי אמר: כתיב\u0004 \u0005[כתוב]\u0006 \u0003\"חדשכם\"\u0004 כלשון יחיד, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ובראשי\"\u0004 לשון רבים — זו כעין סתירה. \u0003ואיזה חדש יש לו שני ראשים — הוי אומר: זה ראש השנה\u0004 שהוא גם ראש השנה וגם ראש חודש, \u0003ואמר רחמנא\u0004 \u0005[ו\u0006בכל זאת \u0005אמרה התורה]\u0006 \u0003\"חדשכם\"\u0004 בלשון יחיד, ללמד כי \u0003חד\u0004 \u0005[אחד]\u0006 \u0003היא\u0004 ואין תוקעים פעמיים.","ו\u0003עוד\u0004 ראיה נוספת כנגד שיטת ר' אחא שיש לתקוע לכל מוסף לחוד, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003בחולו של מועד,\u0004 ביום ה\u0003ראשון\u0004 של חול המועד \u0003מה היו אומרים\u0004 בשיר של קרבן היום — \u0003\"הבו לה' בני אלים\"\u0004 (תהלים כט, א), \u0003בשני מה היו אומרים —\u0004 המזמור שכתוב בו \u0003\"ולרשע אמר אלהים\"\u0004 (תהלים נ, טז), \u0003בשלישי מה היו אומרים —\u0004 מזמור \u0003\"מי יקום לי עם מרעים\"\u0004 (תהלים צד, טו),","\u0003ברביעי מה היו אומרים\u0004 — \u0003\"בינו בוערים בעם\"\u0004 (תהלים צד, ז), \u0003בחמישי מה היו אומרים — \"הסרותי מסבל שכמו\"\u0004 (תהלים פא, ז), \u0003בששי מה היו אומרים — \"ימוטו כל מוסדי ארץ\"\u0004 (תהלים פב, ה). \u0003ואם חל שבת באחד מהם,\u0004 כיון שיש שיר מיוחד של שבת (תהלים פב, צב), שיר אחרון זה של \u0003\"ימוטו\" — ידחה,\u0004 ואת שאר השירים, שלפני השבת ואחריה, אמרו לפי הסדר.","ומעירים: \u0003רב ספרא מנח בהו סימנא\u0004 \u0005[היה נותן בהם סימן],\u0006 לסדר המזמורים בחול המועד, וסימן זה הוא: \u0003\"הומבה\"י\"\u0004 \u0005\"ה\u0006בו \u0005\", \"ו\u0006לרשע\u0005\", \"מ\u0006י\u0005\", \"ב\u0006ינו\u0005\", \"ה\u0006סירותי\u0005\", \"י\u0006מוטו \u0005\"].\u0006 ואילו \u0003רב פפא מנח בהו סמנא\u0004 \u0005[היה נותן בהם סימן],\u0006 שהיה משנה קצת את סדר השירים, ולדעתו היה הסדר: \u0003\"הומהב\"י\"\u0004 שמזמור \"הסירותי\" אומרים לדבריו לפני \"בינו בוערים\". ומעירים: \u0003וסימנך\u0004 שלא תחליף שיטת רב ספרא ברב פפא, מה שאומרים אנו \u0003\"אמבוהא דספרי\"\u0004 \u0005[שיירה של סופרים]\u0006 ויהא זה סימן להלכות, שרב ספרא הוא שאמר סימן מעין אמבוהא (הומבה\"י).","ולענייננו מכאן שוב \u0003תיובתא דר' אחא בר חנינא,\u0004 שהרי מכאן למדים שבשבת היו אומרים רק את מזמור השבת ואין מצרפים לו גם את מזמור החג וממילא אף לא היו תוקעים שתים! ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו. ושואלים: וכיון שהוכחנו מכמה מקורות כנגד דברי ר' אחא, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' אחא בר חנינא קרא ומתניתא קאמר\u0004 \u0005[\u0006גם \u0005כתוב ו\u0006גם \u0005ברייתא אמר]\u0006 להוכיח כדבריו שמספר מחזורי התקיעות לפי מספר המוספים, וכיצד אפשר לדחות דברים אלה לחלוטין?","\u0003אמר רבינא:\u0004 הכתוב והברייתא שהביא לראיה, לא באו ללמד שעושים מחזור תקיעות מיוחד למוסף השני, אלא \u0003לומר שמאריכין בתקיעות\u0004 לכבוד המוסף היתר. כלומר, שהוסיפו באורך כל תקיעה, אולם לא הוסיפו ולו תקיעה אחת. \u0003ורבנן דקיסרי\u0004 \u0005[חכמי קיסריה]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אחא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לומר שמרבה בתוקעין\u0004 שמוסיפים כהנים התוקעים בחצוצרות לכבוד המוסף האחר, אבל לא הוסיפו במספר התקיעות.","אגב הזכרת סדרי מזמורי החג שואלים: \u0003ואנן\u0004 \u0005[ואנו]\u0006 בחוץ לארץ, \u0003דאית לן תרי יומי\u0004 \u0005[שיש לנו שני ימי\u0006 חג\u0005]\u0006 מחמת הספק, \u0003הכי עבדינן\u0004 \u0005[כיצד אנו עושים]\u0006 לגבי הזכרת מוספי החג בימי חול המועד, וכן לגבי קריאת התורה, מה הסדר שבו נוהגים אנו? שהרי בכל יום ויום יש להסתפק איזה יום מימי החג הוא, ואם יזכירו מחמת הספק את אותו יום במשך יומיים רצופים ייצא שביום שמיני עצרת שהוא חג בפני עצמו, יאמרו עדיין את קרבן מוסף של היום השביעי של חג הסוכות! \u0003אביי אמר:\u0004 הזכרת יום \u0003שני ידחה,\u0004 שביום הראשון של חול המועד בחוץ לארץ, שהוא יום שלישי של חג בארץ, אומרים רק קרבן מוסף של \"ביום השלישי\" וכן הלאה. ומשמיטים את היום השני, שהרי היה זה בחוץ לארץ יום חג.","\u0003ורבא אמר: שביעי ידחה,\u0004 שביום הראשון של חול המועד בחוץ לארץ קוראים \"ביום השני\" (אף שהוא מקביל ליום השלישי בארץ ישראל) וכן הלאה, ולבסוף משמיטים את היום השביעי, שאי אפשר לאמרו בשמיני עצרת. ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא: אם חל שבת להיות באחד מהם,\u0004 מימי חול המועד \u0003— \"ימוטו\"\u0004 שהוא המזמור האחרון ושייך ליום השביעי \u0003ידחה\u0004 ואין אומרים אותו.","ומוסיפים: \u0003אתקין\u0004 (התקין) \u0003אמימר\u0004 בעירו \u0003בנהרדעא, דמדלגי דלוגי\u0004 \u0005[שמדלגים],\u0006 שבכל יום מימי חול המועד אומרים שני ימים, את היום הראוי לפי הסדר בארץ ואת היום לפי הסדר בחוץ לארץ, שביום ראשון של חול המועד אומרים \"ביום השני\" ו\"ביום השלישי\", וכן בכולם."],["\u0003יום טוב הראשון של חג\u0004 הסוכות \u0003היו שם שלשה עשר פרים, אילים שנים ושעיר אחד.\u0004 ומעתה דנים בחלוקת עבודת קרבנות החג בין עשרים וארבעה משמרות הכהנים שכולם היו עולים ברגל לעבוד במקדש; את אלה (שלושה עשר הפרים שני האילים והשעיר האחד) היו מחלקים אחד אחד לששה עשר מעשרים וארבעה משמרות הכהנים, \u0003נשתיירו שם\u0004 עוד \u0003ארבעה עשר כבשים\u0004 שאותם היו מחלקים \u0003לשמונה משמרות\u0004 הנותרים. וכיצד היה הסדר: \u0003ביום ראשון\u0004 של חג שהיו ששה עשר משמרות מקריבים שלושה עשר פרים ושני אילים ושעיר אחד, שהם ביחד ששה עשר קרבנות, ונותרו שמונה משמרות הצריכים להקריב. הרי \u0003ששה\u0004 מן המשמרות \u0003מקריבין שנים שנים\u0004 מארבעה עשר הכבשים, שהם ביחד שנים עשר. \u0003והשאר\u0004 שני משמרות האחרים, מקריבים את שני הכבשים הנותרים, \u0003אחד אחד\u0004 לכל משמרת.","\u0003ב\u0004יום ה\u0003שני,\u0004 שבו היו רק שנים עשר פרים, הרי חמישה עשר משמרות מקריבים את הפרים האילים והשעיר, ואילו \u0003חמשה\u0004 משמרות מבין התשעה שנותרו \u0003מקריבין\u0004 מבין הכבשים, כל אחת \u0003שנים שנים,\u0004 שהם עשרה. \u0003והשאר\u0004 ארבעת המשמרות שנותרו, מקריבים כל אחד, \u0003אחד אחד. בשלישי\u0004 שהיו קרבים רק אחד עשר פרים, הרי ארבעה עשר משמרות מקריבים את הפרים האילים והשעיר, ו\u0003ארבעה\u0004 מתוך העשרה שנותרו \u0003מקריבין שנים שנים. והשאר,\u0004 ששת המשמרות האחרים מקריבים כל אחד \u0003אחד אחד.\u0004","\u0003ברביעי\u0004 שהקריבו רק עשרה פרים, הרי שלושה עשר משמרות מקריבים את הפרים האילים והשעיר, ו\u0003שלשה\u0004 מתוך האחד עשר שנותרו \u0003מקריבין שנים שנים, והשאר\u0004 השמונה הנותרים, מקריבים כל אחד \u0003אחד אחד. בחמישי\u0004 שהיו קרבים רק תשעה פרים, הרי שנים עשר משמרות מקריבים את הפרים האילים והשעיר, ו\u0003שנים\u0004 מתוך השנים עשר שנותרו \u0003מקריבין\u0004 כל אחת \u0003שנים שנים. והשאר,\u0004 העשרה הנותרים מקריבים כל אחד \u0003אחד אחד. בששי\u0004 שהיו מקריבים רק שמונה פרים, הרי אחד עשר משמרות מקריבים את הפרים האילים והשעיר, ו\u0003אחד\u0004 מבין השלושה עשר האחרים \u0003מקריב שנים. והשאר\u0004 שנים עשר האחרים מקריבים כל אחד \u0003אחד אחד.\u0004","\u0003בשביעי, כולן שוין.\u0004 שכל אחד מן המשמרות מקריב רק קרבן אחד. \u0003בשמיני,\u0004 שבו סדר קרבנות שונה לגמרי, \u0003חזרו\u0004 לעשות \u0003פייס\u0004 בין כל העשרים וארבעה משמרות \u0003כב\u0004 שאר \u0003רגלים\u0004 שאינם מרובי קרבנות כסוכות. \u0003אמרו\u0004 לגבי סדרי המשמרות: \u0003מי שהקריב פרים היום לא יקריב\u0004 אף \u0003למחר\u0004 פרים \u0003אלא\u0004 משאר סוגי הקרבנות, ו\u0003חוזרים חלילה\u0004 (במעגל), כך שלכל אחד מן המשמרות יהיה גם קרבן פרים וגם מכל סוגי הקרבנות האחרים.","ומציעים: \u0003נימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר\u0006 כי \u0005משנתנו]\u0006 האומרת כי בשמיני חזרו לפייס כבשאר רגלים, כשיטת \u0003רבי היא ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פר הבא ב\u0004קרבן מוסף של \u0003שמיני\u0004 עצרת — \u0003בתחילה מפיסין עליו.\u0004 כלומר, מתחילה עושים פייס מי מן המשמרות יזכה בו, אלו \u0003דברי רבי. וחכמים אומרים: אחת משתי משמרות\u0004 ש\u0003לא שלשו בפרים,\u0004 שכן בין המשמרות היו שנים שהקריבו בחג שני פרים ולא שלושה כאחרים, היא \u0003עושה אותו.\u0004 וכיון שהוזכר במשנתנו פייס, הרי זה כשיטת רבי!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003שתי משמרות לא אפוסי בעי\u0004 \u0005[אינן צריכות לעשות פייס]\u0006 איזו משתיהן תזכה בפר?","ושואלים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת,\u0006 סבורה שיטה \u0005זו, ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל המשמרות שונות ומשלשות\u0004 בקרבן פרים \u0003חוץ משני משמרות ששונות ואין משלשות? נימא\u0004 \u0005[האם נאמר]\u0006 שהוא כשיטת \u0003רבי ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שהרי לדעת חכמים אחת משתי המשמרות האלה תשלש בשמיני עצרת! ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לא שלשו —\u0004 כוונתו \u0003בפרי החג\u0004 של סוכות בלבד.","ואם תאמר, אם כן \u0003ומאי קא משמע לן\u0004 \u0005[ומה השמיע לנו\u0006 בזה\u0005],\u0006 הרי ענין של חשבון פשוט הוא! יש לומר כי \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 כי \u0003מי שהקריב פרים היום\u0004 — \u0003לא יקריב למחר, אלא חוזרין חלילה,\u0004 ולכן כהכרח מקריב כל משמר לפחות שנים, ורובם שלושה פרים.","\u0003אמר ר' אלעזר: הני\u0004 \u0005[אותם]\u0006 \u0003שבעים פרים\u0004 שמביאים בסך הכל כמוספי שבעת ימי חג הסוכות \u0003כנגד מי\u0004 מביאים אותם — \u0003כנגד שבעים אומות,\u0004 שמביאים אותם לכפרתן, ומתוך שכפרתן בחג הסוכות שבו נידונים על המים, ימטיר ה' גשמי ברכה לעולם. \u0003פר יחידי\u0004 של שמיני \u0003למה — כנגד אומה יחידה,\u0004 ישראל.","\u0003משל למלך בשר ודם שאמר לעבדיו: עשו לי סעודה גדולה\u0004 הנמשכת ימים אחדים. אחרי שסיימו את הסעודה \u0003ליום אחרון, אמר לאוהבו: עשה לי סעודה קטנה\u0004 רק עבורי \u0003כדי שאהנה ממך\u0004 במיוחד.","והוסיף \u0003ואמר ר' יוחנן: אוי להם לאומות העולם שאבדו ואין יודעים מה שאבדו.\u0004 ש\u0003בזמן שבית המקדש קיים מזבח מכפר עליהן\u0004 בשבעים פרי החג, \u0003ועכשיו\u0004 שחרב המקדש \u0003מי מכפר עליהן?\u0004","\u0003בשלשה פרקים\u0004 (זמנים) \u0003בשנה היו כל משמרות שוות,\u0004 שהיו כולם מקבלים חלק בעבודה ובמתנות הכהונה הנלוות לה בלי לשים לב לתור הקבוע של סדר המשמרות: \u0003באימורי\u0004 (בקרבנות) \u0003הרגלים ובחילוק לחם הפנים\u0004 בשבת, כשחלה זו בתוך אחד הרגלים","\u0003ובעצרת\u0004 (בחג השבועות) בחלוקת שתי הלחם, אם חל ביום השבת, שאז מחלקים גם את לחם הפנים, ומתחלק כאמור לכל עשרים וארבעת המשמרות, ואז \u0003אומר לו\u0004 המחלק לכל כהן בשעה שמקבל חלקו: \u0003הילך מצה\u0004 מלחם הפנים, ובנוסף \u0003הילך חמץ\u0004 משתי הלחם. כלל הוא כי \u0003משמר שזמנו קבוע,\u0004 כלומר: המשמר שלפי הסדר הגיע תורו לעבוד בשבוע החג \u0003הוא מקריב\u0004 את כל הקרבנות שאינם באים במיוחד בשביל הרגל, וכגון: \u0003תמידין\u0004 של כל ימות החג וכן \u0003נדרים ונדבות ושאר קרבנות צבור — ומקריב את הכל\u0004 אפילו בחג.","על לשון המשנה תוהים: כיצד זה מתחלקים הכהנים באימורי הרגלים? הלא \u0003אימורי הרגלים\u0004 שהם חלב הקרבנות \u0003של גבוה נינהו\u0004 \u0005[הם],\u0006 שהרי כולם עולים למזבח, ומה שייך עניין חלוקה למשמרות הכהנים בזה? \u0003אמר רב חסדא:\u0004 הכוונה היא \u0003למה שאמור ברגלים.\u0004 כלומר: כל חלקי הקרבנות שאמרה התורה להביא ברגל וראויים להתחלק, כגון עורותיהם של עולות ראיה (שמביאים כבשיהם להראות במקדש) וחזה ושוק משלמי חגיגה, וכיוצא בהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שכל המשמרות שוות באימורי הרגלים — תלמוד לומר\u0004 \"וכי יבוא הלוי מאחד שעריך מכל ישראל אשר הוא גר שם \u0003ובא בכל אות נפשו\u0004 אל המקום אשר יבחר ה'. \u0003ושרת\u0004 בשם ה' אלהיו ככל אחיו הלוים העומדים שם לפני ה'. חלק כחלק יאכלו לבד ממכריו על האבות\" (דברים יח, ו-ח), לומר שאין המשמר הקבוע זוכה באימורים, אלא המשמר שהקריב הוא זה שגם זוכה במתנות הכהונה הבאות כתוצאה מעבודתו. \u0003יכול אף בשאר ימות השנה כן\u0004 שכל המשמרות יהיו שווים בעבודה — \u0003תלמוד לומר: \"מאחד שעריך\"\u0004 (דברים יח, ו), \u0003לא אמרתי\u0004 שהכל שווים \u0003אלא בשעה שכל ישראל נכנסין בשער אחד,\u0004 כלומר: שכולם באים יחד, והוא בשעת הרגל.","שנינו במשנה כי בשלושת הרגלים כל עשרים וארבעת המשמרות שווים \u0003בחילוק לחם הפנים. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שכל המשמרות שוות בחילוק לחם הפנים —\u0004"],["\u0003תלמוד לומר: \"חלק כחלק יאכלו\"\u0004 (דברים יח, ח). ומשמעו: \u0003כחלק עבודה — כך חלק אכילה,\u0004 שכל הכהנים מתחלקים גם באוכל. ומעתה נדון: \u0003ומאי\u0004 \u0005[ומה\u0006 היא\u0005]\u0006 \u0003אכילה\u0004 זו שמדובר בה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ב\u0003קרבנות —\u0004 אין צורך בפסוק זה, כי \u0003מהתם נפקא\u0004 \u0005[משם\u0006 מפסוק אחר \u0005יוצא\u0006 נלמד הדבר\u0005],\u0006 שנאמר: \u0003\"לכהן המקריב אותה לו תהיה\"\u0004 (ויקרא ז, ט) וכן בשאר הקרבנות שם, לומר שכהן העובד בקרבנות יש לו חלק באכילתם. \u0003אלא\u0004 הכוונה היא ל\u0003לחם הפנים\u0004 שלא היתה בו עבודה בשבת זו אלא נאפה בשבת קודמת.","\u0003יכול\u0004 יהיו הכל שווים \u0003אף בחובות הבאות שלא מחמת הרגל ברגל,\u0004 שהרי יש קרבנות רבים כגון נדרים ונדבות שאינם קשורים דווקא למצוות הרגל, אלא אנשים משתמשים בהזדמנות שהם עולים לירושלים, כדי להקריב את שנדרו ונדבו במשך השנה, \u0003תלמוד לומר: \"לבד ממכריו על האבות\"\u0004 (דברים יח, ח) — \u0003מה מכרו האבות\u0004 ראשי המשמרות הראשונים \u0003זה לזה —\u0004 את עבודת המשמרות לפי סדר מסויים, שלפיו \u0003\"אני בשבתי ואתה בשבתך\"\u0004 וניתנת איפוא הזכות לכל משמר לעבוד בשבוע מסויים בשנה ולקבל את מתנות הכהונה הבאות מן הקרבנות הקרבים באותו שבוע.","שנינו במשנה כי כך היו מחלקים: \u0003בעצרת אומר לו הילך\u0004 מצה, הילך חמץ. ומביאים בעיה שנחלקו בה האמוראים, \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003רב אמר:\u0004 כשנכנס אדם לשבת בסוכה ועומד לברך על מצוה זו, הריהו מברך בתחילה על ה\u0003סוכה\u0004 (\"ברוך... אשר קדשנו במצוותיו וציונו לישב בסוכה\"), \u0003ואחר כך\u0004 מברך על ה\u0003זמן\u0004 (\"שהחיינו\"). \u0003רבה בר בר חנה אמר:\u0004 קודם ברכת ה\u0003זמן, ואחר כך\u0004 ברכת ה\u0003סוכה.\u0004","ומסבירים את טעמיהם. \u0003רב אמר: סוכה ואחר כך זמן,\u0004 שכן \u0003חיובא דיומא עדיף\u0004 \u0005[חובת היום עדיפה]\u0006 ויש איפוא להקדימה. \u0003ורבה בר בר חנה אמר: זמן ואחר כך סוכה,\u0004 וטעמו: \u0003תדיר ושאינו תדיר — תדיר קודם,\u0004 וברכת \"שהחיינו\" מצויה יותר.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003רב ורבה בר בר חנה בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003בית שמאי ובית הלל קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא: אלו הם ה\u0003דברים ש\u0004בהם חלוקות הדעות \u0003בין בית שמאי ובית הלל ב\u0004הלכות \u0003סעודה, בית שמאי אומרים:\u0004 בשעת קידוש של שבת \u0003מברך\u0004 תחילה \u0003על היום\u0004 (על השבת) \u0003ואחר כך מברך על היין\u0004 (\"בורא פרי הגפן\"), \u0003ובית הלל אומרים: מברך על היין ואחר כך מברך על היום.\u0004","ומסבירים, \u0003בית שמאי אומרים: מברך על היום ואחר כך מברך על היין — ש\u0004הרי \u0003היום גורם ליין שיבא,\u0004 שהרי לא היו שותים יין לולא חובת הקידוש, וטעם נוסף: \u0003וכבר קידש היום\u0004 תחילה \u0003ועדיין יין לא בא,\u0004 וכיון שקדושת שבת קדמה בזמן לחובת ברכת היין — יש איפוא להקדימה. \u0003ובית הלל אומרים: מברך על היין ואחר כך מברך על היום,\u0004 מפני \u0003שהיין גורם לקידושא\u0004 \u0005[לקידוש]\u0006 \u0003שתאמר,\u0004 שהרי אין אומרים קידוש אלא על היין, ואם כן היין עיקר. \u0003דבר אחר: ברכת היין\u0004 ברכה \u0003תדירה\u0004 היא, \u0003וברכת היום\u0004 (השבת) \u0003אינה תדירה\u0004 כמוה, ויש לנקוט להלכה לפי הכלל: \u0003תדיר ושאינו תדיר — תדיר קודם.\u0004","ומעתה \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003רב אמר כבית שמאי,\u0004 שיש להעדיף את חובת היום על התדיר, \u0003ורבה בר בר חנה אמר כבית הלל,\u0004 שיש להעדיף את התדיר!","ודוחים: \u0003אמר לך רב\u0004 \u0005[\u0006יכול היה \u0005רב לומר לך]:\u0006 \u0003אנא דאמרי\u0004 \u0005[אני שאומר\u0006 את דברי\u0005],\u0006 הרי הם \u0003אפילו ל\u0004שיטת \u0003בית הלל,\u0004 אלא שיש לחלק: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[שאמרו]\u0006 \u0003בית הלל התם\u0004 \u0005[שם]\u0006 \u0003אלא שהיין גורם לקידושא\u0004 \u0005[לקידוש]\u0006 \u0003שתאמר, אבל הכא\u0004 \u0005[כאן]\u0006 אין קשר כזה בין הדברים, שהרי \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ברכת \u0003זמן, מי לא אמרינן\u0004 \u0005[האם לא היינו אומרים]\u0006 ברכת \u0003סוכה,\u0004 והלא מברכים על הסוכה בשאר הימים ללא ברכת \"שהחיינו\".","ומצד שני, \u0003ורבה בר בר חנה אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: אנא דאמרי\u0004 \u0005[אני שאמרתי\u0006 את דברי\u0005],\u0006 \u0003אפילו לבית שמאי\u0004 אומר אני. כי \u0003עד כאן לא\u0004 שמענו כי \u0003אמרי\u0004 \u0005[שאמרו]\u0006 \u0003בית שמאי התם\u0004 \u0005[שם]\u0006 \u0003אלא\u0004 מפני \u0003שהיום גורם ליין שיבא, אבל הכא\u0004 \u0005[כאן]\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ברכת ה\u0003סוכה מי לא אמרינן\u0004 \u0005[האם לא היינו אומרים]\u0006 את ברכת ה\u0003זמן\u0004 (\u0005\"\u0006שהחיינו\") על החג עצמו, גם אם אינו יושב בסוכה? ומעתה מנסים להביא ראיה לשיטות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003בעצרת אומר לו הילך מצה, הילך חמץ. והא הכא\u0004 \u0005[והרי כאן]\u0006 שה\u0003חמץ\u0004 הוא \u0003עיקר ומצה טפל\u0004 שהרי מדובר בחג השבועות (\"עצרת\") ושתי הלחם שמהן מחלקים את החמץ, הן קרבן היום, \u0003וקתני הילך מצה והילך חמץ\u0004 ובכל זאת מקדימים את חלוקת לחם הפנים שהיא תדירה, שהרי היא נעשית בכל שבת, על מצות היום, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב!\u0004","ומשיבים: \u0003אמר לך רב\u0004 \u0005[\u0006יכול היה \u0005רב לענות לך]\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בזה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 כך אומר המחלק: \u0003הילך מצה, הילך חמץ. אבא שאול אומר:\u0004 לא כך אומר, אלא \u0003הילך חמץ, הילך מצה.\u0004","ולפסק ההלכה \u0003דרש רב נחמן בר רב חסדא: לא כדברי רב\u0004 ש\u0003אמר\u0004 כי קודם יש לברך על ה\u0003סוכה ואחר כך\u0004 על ה\u0003זמן, אלא\u0004 יש לברך תחילה על ה\u0003זמן ואחר כך\u0004 על ה\u0003סוכה.\u0004 לעומת זאת \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר:\u0004 יש לברך תחילה על ה\u0003סוכה ואחר כך\u0004 על ה\u0003זמן,\u0004 כשיטת רב. ומעירים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 כדברי רב: \u0003סוכה ואחר כך זמן.\u0004","נאמר במשנה כי \u0003משמר שזמנו קבוע\u0004 לפי התור, מביא: תמידים, נדרים, נדבות \u0003ושאר קרבנות צבור.\u0004 ושואלים: כשאומרים \"שאר קרבנות ציבור\", \u0003לאתויי מאי\u0004 \u0005[להביא מה],\u0006 מה הם קרבנות הציבור האחרים הנכללים בכלל זה? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003פר העלם דבר של צבור.\u0004 אם יזדמן להביא קרבן זה של חטאת על שגגה שעשה הציבור כולו בהוראת בית דין, אף שאין לו זמן קבוע, מכל מקום בכלל קרבנות הציבור הוא. \u0003ושעירי עבודה זרה\u0004 שמביא הציבור ככפרה על שגגתו בעבירה זו, שאם נזדמן להביאם אז — הרי הם חלק מעבודת המשמר הקבוע.","נאמר עוד במשנה \u0003והוא\u0004 המשמר שתורו לעבוד באותו שבוע, \u0003מקריב את הכל.\u0004 ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 להוסיף \u0005מה]\u0006 באו דברים אלה? ומסבירים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 את \u0003קייץ המזבח.\u0004 שבכל עת שלא היה כל קרבן מוקרב על המזבח, היו מביאים קרבנות עולה מיוחדים כנדבת הציבור מפני כבוד שכינה שלא יהיה המזבח ריק, ואף קרבנות אלה מקריב המשמר הקבוע.","ב\u0003יום טוב הסמוך לשבת, בין מלפניה בין לאחריה\u0004 — \u0003היו כל המשמרות\u0004 שכולם הגיעו או נשארו לעבודת הרגלים \u0003שוות בחילוק לחם הפנים\u0004 בשבת זו. ואם \u0003חל להיות יום אחד להפסיק בינתים\u0004 בין יום טוב ושבת — \u0003משמר שזמנו קבוע\u0004 לשבת זו \u0003היה נוטל עשר\u0004 משתים עשרה \u0003חלות\u0004 לחם הפנים, והמשמר \u0003המתעכב\u0004 שנשאר מיום טוב ולא הספיק לחזור למקומו \u0003נוטל שתים\u0004 מהן. \u0003ובשאר ימות השנה\u0004 כאשר הכל נוהג כסדרו והמשמרות מתחלפות בשבת — המשמר \u0003הנכנס נוטל שש והיוצא נוטל שש. ר' יהודה אומר: הנכנס נוטל שבע והיוצא נוטל חמש.\u0004","כלל היה בענין זה: \u0003הנכנסין\u0004 (בני המשמר הנכנס) \u0003חולקין\u0004 את לחם הפנים כשהם מצויים \u0003בצפון\u0004 העזרה \u0003והיוצאין\u0004 עומדים בעת החלוקה \u0003בדרום.\u0004 אולם היה יוצא אחד מן הכלל, כי משמר \u0003בילגה,\u0004 משום קנס שקנסו אותו (כפי שיבואר בגמרא) \u0003לעולם חולקת בדרום\u0004 גם כשהיא משמר הנכנס. \u0003וטבעתה\u0004 שהיו מכינים למשמרות הכהונה טבעות כדי לסייע בשחיטת הקרבנות \u0003קבועה\u0004 באופן שלא יוכלו להשתמש בה, \u0003וחלונה\u0004 בין החלונות שהיו בכתלי לישכת בית החליפות, שבהם היו הכהנים מניחים את הסכינים ושאר הכלים — היתה \u0003סתומה.\u0004","שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הפירוש \u0003מלפניה ומאי\u0004 \u0005[ומה]\u0006 הפירוש \u0003מלאחריה? אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003מלפניה\u0004 כוונתו \u0003יום טוב ראשון\u0004 של חג, \u0003לאחריה — יום טוב אחרון,\u0004 אם כן \u0003היינו\u0004 \u0005[הרי זו]\u0006 \u0003שבת שבתוך החג,\u0004 ויכול היה לומר כך בפשטות.","\u0003אלא\u0004 יש לומר: \u0003לפניה —\u0004 הכוונה היא \u0003יום טוב אחרון\u0004 של חג שחל ביום שישי. \u0003לאחריה — יום טוב ראשון\u0004 שהיה ביום ראשון. \u0003ומאי טעמא\u0004 \u0005[ומה הטעם]\u0006 לתקנה זו — \u0003כיון דהני מקדמי והני מאחרי\u0004 \u0005[שאלה מקדימים ואלה מאחרים],\u0006 שהרי היוצא אינו יכול לצאת בשל השבת, וכן המשמר הנכנס צריך להקדים, לכך \u0003תיקנו רבנן\u0004 \u0005[חכמים]\u0006 \u0003מילתא\u0004 \u0005[דבר\u0006 זה\u0005]\u0006 \u0003כי היכי דניכלו בהדי הדדי\u0004 \u0005[כדי שיאכלו יחד].\u0006","שנינו במשנה כי אם \u0003חל\u0004 להיות \u0003יום אחד\u0004 המפסיק בין יום טוב לשבת היה המשמר הקבוע לאותו יום נוטל עשר חלות והיוצא נוטל שתים. ובשאר ימות השנה היה הנכנס נוטל שש והיוצא שש. ואילו לר' יהודה משמר הנכנס היה נוטל שבע חלות, שתים יותר מן המשמר היוצא."],["\u0003והני תרתי מאי עבידתייהו\u0004 \u0005[ואותן שתי\u0006 חלות יתירות \u0005מה מעשיהן],\u0006 כלומר: מפני מה ניתנו להם? \u0003אמר ר' יצחק: בשכר הגפת דלתות\u0004 כתמורה על עבודת נעילת דלתות המקדש שנפתחו על ידי המשמר היוצא ואותן היה סוגר המשמר הנכנס. ושואלים: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 המשמר היוצא למשמר הנכנס \u0003דל בדל\u0004 \u0005[הסר\u0006 את שלך \u0005ואסיר\u0006 את שלי\u0005],\u0006 כלומר: הבה נבטל תקנה זו, ונחלק בשווה, ולשבת הבאה כשתהיה אתה המשמר היוצא תרויח גם אתה שתיטול בשווה עם המשמר הנכנס! \u0003אמר אביי: בוצינא טבא מקרא\u0004 \u0005[קישוא\u0006 שכבר בשל כעת, למרות קוטנו \u0005טוב\u0006 לי \u0005מדלעת\u0006 גדולה שתתבשל לאחר זמן\u0005].\u0006 כלומר: אין אנשים רוצים לוותר על רווח קטן הבא להם מיד על מנת להרויח יותר לאחר זמן.","\u0003אמר רב יהודה:\u0004 ובקרבנות \u0003המוספין חולקין\u0004 המשמר הנכנס והיוצא בעורות העולות. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003משמרה היוצאת עושה תמיד של שחר ומוספין, משמרה הנכנסת עושה תמיד בין הערבים ובזיכין\u0004 (קטורת שעל לחם הפנים) \u0003ואילו מוספין חולקין לא קתני\u0004 \u0005[שנה]!\u0006 ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא ב\u0004עניינים הקשורים ל\u0003חלוקה לא קא מיירי\u0004 \u0005[אינו דן],\u0006 אלא רק בעבודה עצמה, ולכן לא הזכיר את סדר החלוקה.","\u0003אמר רבא: והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל, דמיירי\u0004 \u0005[ש\u0006הוא \u0005עוסק]\u0006 \u0003בחלוקה\u0004 ובכל זאת \u0003\"ובמוספין חולקין\" לא קתני\u0004 \u0005[שנה]?\u0006 \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל\u0004 ברייתא זו: \u0003משמרה היוצאת עושה תמיד של שחר ומוספין, משמרה הנכנסת עושה תמיד של בין הערבים ובזיכין.\u0004 וכיצד נעשתה עבודת הבזיכים — \u0003ארבעה כהנים היו נכנסין שם\u0004 להיכל \u0003שנים ממשמר זו\u0004 (היוצא) \u0003ושנים ממשמר זו\u0004 (הנכנס), \u0003וחולקין\u0004 ביניהם את \u0003לחם הפנים. ואילו \"במוספין חולקין\" לא קתני\u0004 \u0005[שנה]!\u0006 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 על שיטת \u0003רב יהודה\u0004 האומר כי היו חולקים אף במוספים! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","שנינו במשנה כי \u0003הנכנסין חולקין בצפון\u0004 והיוצאים היו עומדים בשעת החלוקה בדרום. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הנכנסין חולקין בצפון\u0004 שהוא מקודש יותר \u0003כדי שיראו שהן נכנסין, והיוצאין חולקין בדרום כדי שיראו שהן יוצאין.\u0004","אולם שנינו כי משמר \u0003בילגה\u0004 כאמור במשנה \u0003לעולם חולקת בדרום,\u0004 אף כשהיתה משמר הנכנס. את דינו של משמר בילגה מסבירים בברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה במרים בת\u0004 משמר \u0003בילגה שהמירה דתה והלכה ונשאת לסרדיוט\u0004 (לאיש צבא) \u0003אחד\u0004 שהיה משרת בצבא \u0003ממלכי\u0004 ה\u0003יוונים. כשנכנסו יוונים להיכל\u0004 נכנסה היא עמהם ו\u0003היתה מבעטת בסנדלה על גבי\u0004 ה\u0003מזבח ואמרה: לוקוס לוקוס\u0004 \u0005[זאב, זאב]!\u0006 \u0003עד מתי אתה מכלה ממונן של ישראל ואי אתה עומד עליהם בשעת הדחק! וכששמעו חכמים\u0004 לאחר נצחון בית חשמונאי על היוונים \u0003בדבר\u0004 שכך ביזתה את המזבח, \u0003קבעו את טבעתה\u0004 של משמר בילגה באופן שלא יהיה ראוי לשימוש \u0003וסתמו את חלונה.\u0004","\u0003ויש אומרים:\u0004 שהמשמר נקנס מטעם אחר — שפעם היתה \u0003משמרתו\u0004 של בילגה \u0003שוהה לבא,\u0004 כלומר שהתעצלו בני המשמר ולא הגיעו בזמן, \u0003ונכנס\u0004 משמר \u0003ישבב אחיו\u0004 שהוא המשמר שבאופן קבוע היה תורו לעבוד בשבוע שלאחרי משמר בילגה \u0003עמו ושימש תחתיו,\u0004 שהמשמר הבא אחריו היה צריך לשרת אתו עד שיבואו כל בני משמר בילגה. ומעירים: \u0003אף על פי\u0004 שבדרך כלל \u0003שכיני רשעים לא נשתכרו\u0004 (הרויחו), שהרי אוי לרשע ואוי לשכנו, אולם \u0003שכיני בילגה\u0004 בכל אופן \u0003נשתכרו, ש\u0004הרי \u0003בילגה לעולם חולקת בדרום,\u0004 אף בכניסתה, \u0003וישבב אחיו בצפון,\u0004 אף ביציאתה.","ומבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שנקנס משמר בילגה מפני ש\u0003משמרתו שוהה לבא — היינו דקנסינן לכולה\u0004 \u0005[זהו שקונסים אנו את כל]\u0006 ה\u0003משמר, אלא ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 משום \u0003מרים בת בילגה שהמירה דתה, משום ברתיה קנסינן ליה לדידיה\u0004 \u0005[משום בתו קונסים אנו אותו]?\u0006 \u0003אמר אביי: אין\u0004 \u0005[כן],\u0006 והטעם הוא \u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים בני אדם]\u0006 בפתגם מקובל: \u0003שותא דינוקא בשוקא, או דאבוה או דאימיה\u0004 \u0005[שיחתו של תינוק בשוק, או משל אביו או משל אמו],\u0006 ומרים בת בילגה לא היתה אומרת דברים אלה לולא שמעה כגון זה בבית הוריה.","ושואלים: \u0003ומשום אבוה ואימיה קנסינן לכולה\u0004 \u0005[אביה ואמה\u0006 של מרים זו \u0005קונסים אנו\u0006 את \u0005כל]\u0006 ה\u0003משמרה? אמר אביי:\u0004 כבר אמרו \u0003אוי לרשע אוי לשכינו.\u0004 ומסיימים את המסכת בדבר טוב: \u0003טוב לצדיק וטוב לשכינו, שנאמר: \"אמרו צדיק כי טוב כי פרי מעלליהם יאכלו\"\u0004 (ישעיהו ג, י) שאף שכני הצדיק אומרים כי טוב — שהם נהנים מקרבתו.",""]]};
